import { mixins as walletMixins, WALLET_CONSTS } from '@wallet';
import isEqual from 'lodash/fp/isEqual';
import { Options, Watch, mixins as vueMixins } from 'vue-property-decorator';

import { type FetchVariables } from '@/types/indexers';
import { debouncedInputHandler } from '@/utils';

@Options({})
export default class IndexerDataFetchMixin extends vueMixins(walletMixins.LoadingMixin, walletMixins.PaginationSearchMixin) {
  totalCount = 0;
  items: readonly any[] = [];

  pageAmount = 5;
  fetchAmount = 5;

  private interval: Nullable<ReturnType<typeof setInterval>> = null;
  private updateItems = debouncedInputHandler(this.updateData, 250, { leading: false });

  updateInterval = 24_000; // 4 blocks

  get intervalTimestamp(): number {
    return Math.floor(this.getItemTimestamp(this.items[0]) / 1000);
  }

  get loadingState(): boolean {
    return this.parentLoading || this.loading;
  }

  // override PaginationSearchMixin
  get total(): number {
    return this.totalCount;
  }

  get hasItems(): boolean {
    return this.total > 0;
  }

  get dataVariables(): FetchVariables {
    return {};
  }

  get updateVariables(): FetchVariables {
    return {};
  }

  get fetchPage(): number {
    return Math.ceil((this.pageAmount * this.currentPage) / this.fetchAmount);
  }

  get visibleItems(): any[] {
    const offset = this.fetchAmount * (this.fetchPage - 1);
    const start = this.pageAmount * (this.currentPage - 1) - offset;
    const end = start + this.pageAmount;

    return this.items.slice(start, end);
  }

  @Watch('fetchPage')
  private checkPageToLoad(): void {
    this.updateItems();
  }

  checkTriggerUpdate(current: any, prev: any) {
    if (!isEqual(current)(prev)) {
      this.resetPage();
      this.resetItems();
      this.updateItems();
    }
  }

  async requestData(variables: FetchVariables): Promise<{ items: any[]; totalCount: number }> {
    console.info('[IndexerDataFetchMixin]: requestData is not implemented');
    return { items: [], totalCount: 0 };
  }

  getItemTimestamp(item: any): number {
    console.info('[IndexerDataFetchMixin]: getItemTimestamp is not implemented');
    return 0;
  }

  public handlePaginationClick(button: WALLET_CONSTS.PaginationButton): void {
    let current = 1;

    switch (button) {
      case WALLET_CONSTS.PaginationButton.Prev:
        current = this.currentPage - 1;
        break;
      case WALLET_CONSTS.PaginationButton.Next:
        current = this.currentPage + 1;
        break;
      case WALLET_CONSTS.PaginationButton.Last:
        current = this.lastPage;
        break;
    }

    this.currentPage = current;
  }

  private async updateData(): Promise<void> {
    this.resetDataSubscription();

    await this.fetchData();

    if (this.fetchPage === 1) {
      this.subscribeOnData();
    }
  }

  private resetItems(): void {
    this.items = [];
    this.totalCount = 0;
  }

  private async fetchData(): Promise<void> {
    await this.withLoading(async () => {
      await this.withParentLoading(async () => {
        const { totalCount, items } = await this.requestData(this.dataVariables);
        this.items = Object.freeze([...items]);
        this.totalCount = totalCount;
      });
    });
  }

  private async fetchDataUpdates(): Promise<void> {
    const { items, totalCount } = await this.requestData(this.updateVariables);
    this.items = Object.freeze([...items, ...this.items].slice(0, this.fetchAmount));
    this.totalCount = this.totalCount + totalCount;
  }

  private subscribeOnData(): void {
    this.resetDataSubscription();
    this.interval = setInterval(() => this.fetchDataUpdates(), this.updateInterval);
  }

  private resetDataSubscription(): void {
    if (this.interval) {
      clearInterval(this.interval);
    }
    this.interval = null;
  }

  beforeDestroy(): void {
    this.resetDataSubscription();
  }
}

import { BalanceType } from '@sora-substrate/sdk/build/assets/consts';

import { useFormattedAmount } from '@/composables/useFormattedAmount';
import { useNumberFormatter } from '@/composables/useNumberFormatter';
import type { Nullable } from '@/types/common';
import {
  asZeroValue,
  formatAmountWithSuffix,
  formatAssetBalance as baseFormatAssetBalance,
} from '@/utils/asset-formatting';

import type { CodecString, FPNumber } from '@sora-substrate/sdk';
import type { AccountAsset, Asset, RegisteredAccountAsset } from '@sora-substrate/sdk/build/assets/types';

type AssetWithBalance = AccountAsset | RegisteredAccountAsset;

export type FormatAssetBalanceOptions = {
  internal?: boolean;
  formattedZero?: string;
  showZeroBalance?: boolean;
  balanceType?: BalanceType;
};

export type AssetDisplay = {
  value: string;
  fiat: Nullable<string>;
};

const extractBalance = (
  asset: AssetWithBalance,
  balanceType: BalanceType = BalanceType.Transferable
): Nullable<CodecString> => {
  const balance = (asset as AccountAsset)?.balance;
  if (!balance) return null;

  if (balanceType === BalanceType.Transferable) return balance.transferable ?? null;
  return (balance as Record<string, CodecString | undefined>)[balanceType] ?? null;
};

/**
 * Consolidated asset formatting helpers wrapping the legacy mixins and
 * existing composables (`useFormattedAmount`, `useNumberFormatter`).
 */
export function useAssetFormatting() {
  const formattedAmount = useFormattedAmount();
  const numberFormatter = useNumberFormatter();

  const formatAssetBalance = (
    asset: Nullable<AssetWithBalance>,
    options: FormatAssetBalanceOptions = {}
  ): string => {
    if (!asset) return options.formattedZero ?? '';

    const { internal = true, formattedZero = '', showZeroBalance = true, balanceType = BalanceType.Transferable } =
      options;

    if (!internal) {
      return baseFormatAssetBalance(asset, { internal, formattedZero, showZeroBalance });
    }

    const balance = extractBalance(asset, balanceType);
    if (!balance || (!showZeroBalance && asZeroValue(balance))) {
      return formattedZero;
    }

    return numberFormatter.formatCodecNumber(balance, (asset as AccountAsset).decimals);
  };

  const formatAssetDisplay = (
    asset: Nullable<AccountAsset>,
    options: FormatAssetBalanceOptions = {}
  ): AssetDisplay => {
    const value = formatAssetBalance(asset ?? null, options);
    const balanceType = options.balanceType ?? BalanceType.Transferable;
    const fiat = asset ? formattedAmount.getFiatBalance(asset, balanceType) : null;

    return { value, fiat };
  };

  const formatAmountWithFiat = (
    amount: string | CodecString,
    asset: Asset | AccountAsset,
    isCodecString = false
  ): Nullable<string> => {
    return formattedAmount.getFiatAmount(amount, asset, isCodecString);
  };

  const formatAmountWithSuffixHelper = (value: FPNumber, precision?: number) =>
    formatAmountWithSuffix(value, precision);

  return {
    ...formattedAmount,
    ...numberFormatter,
    formatAssetBalance,
    formatAssetDisplay,
    formatAmountWithFiat,
    formatAmountWithSuffix: formatAmountWithSuffixHelper,
  };
}

export type AssetFormattingComposable = ReturnType<typeof useAssetFormatting>;

import { computed, ref, type ComputedRef, type Ref } from 'vue';

import { useAssetsStore } from '@/stores/assets';
import { useWalletStore } from '@/stores/wallet';
import { filterAssetsByQuery, type AssetSearchOptions } from '@/composables/useAssetSearch';
import type { Nullable } from '@/types/common';
import { sortAssets } from '@/utils/asset-sort';

import type { AccountAsset, RegisteredAccountAsset } from '@sora-substrate/sdk/build/assets/types';

type AssetBalanceCandidate = AccountAsset | RegisteredAccountAsset;

const isBalanceEmpty = (asset: AccountAsset | RegisteredAccountAsset): boolean => {
  const transferable = (asset as AccountAsset)?.balance?.transferable ?? null;
  if (transferable === null || transferable === undefined) return true;
  return Number(transferable) === 0;
};

export type UseAssetsOptions = {
  /**
   * Optional set of asset addresses that will be excluded from the returned lists.
   */
  exclude?: readonly string[];
  /**
   * When false, zero-balance assets are filtered out from the `filteredAccountAssets` list.
   * Defaults to true (keep zero-balance assets).
   */
  includeZeroBalance?: boolean;
  /**
   * Additional search behaviour overrides passed to `filterAssetsByQuery`.
   */
  searchOptions?: AssetSearchOptions;
};

type RegisteredAssetsMap = Record<string, RegisteredAccountAsset>;

/**
 * Shared asset helpers that wrap the wallet Pinia stores and expose
 * filtering/sorting utilities for asset dialogs and selectors.
 */
export function useAssets(options: UseAssetsOptions = {}) {
  const walletStore = useWalletStore();
  const assetsStore = useAssetsStore();

  const excludedAddresses = computed(() => new Set(options.exclude ?? []));

  const compareByBalance = (a: AssetBalanceCandidate, b: AssetBalanceCandidate): number => {
    const aEmpty = isBalanceEmpty(a);
    const bEmpty = isBalanceEmpty(b);

    if (aEmpty === bEmpty) {
      return sortAssets(a, b);
    }

    return aEmpty && !bEmpty ? 1 : -1;
  };

  const sortByBalance = compareByBalance;

  const accountAssets: ComputedRef<AccountAsset[]> = computed(
    () => (walletStore.accountAssets as AccountAsset[]) ?? []
  );

  const sortedAccountAssets = computed<AccountAsset[]>(() =>
    accountAssets.value
      .filter((asset) => !excludedAddresses.value.has(asset.address))
      .slice()
      .sort((a, b) => compareByBalance(a, b))
  );

  const search: Ref<string> = ref('');

  const filteredAccountAssets = computed<AccountAsset[]>(() => {
    const baseList =
      options.includeZeroBalance === false
        ? sortedAccountAssets.value.filter((asset) => !isBalanceEmpty(asset))
        : sortedAccountAssets.value;

    return filterAssetsByQuery(baseList, search.value, options.searchOptions);
  });

  const getAssetsWithBalances = (
    addresses: readonly string[],
    exclude: Nullable<string | readonly string[]> = null
  ): RegisteredAccountAsset[] => {
    const exclusion = new Set<string>(options.exclude ?? []);
    if (exclude) {
      const extra = Array.isArray(exclude) ? exclude : [exclude];
      extra.forEach((address) => exclusion.add(address));
    }

    const resolve = assetsStore.assetDataByAddress as (address?: string) => Nullable<RegisteredAccountAsset>;

    const collection: RegisteredAccountAsset[] = [];
    addresses.forEach((address) => {
      if (exclusion.has(address)) return;
      const asset = resolve(address);
      if (asset) {
        collection.push(asset);
      }
    });

    return collection.sort((a, b) => compareByBalance(a, b));
  };

  const registeredAssets = computed<RegisteredAccountAsset[]>(() => {
    const entries = (assetsStore.registeredAssets ?? {}) as RegisteredAssetsMap;
    return getAssetsWithBalances(Object.keys(entries));
  });

  const filteredRegisteredAssets = computed<RegisteredAccountAsset[]>(() =>
    filterAssetsByQuery(
      registeredAssets.value,
      search.value,
      {
        useExternalAddress: options.searchOptions?.useExternalAddress ?? true,
      }
    )
  );

  const getAssetByAddress = (address?: string): Nullable<RegisteredAccountAsset> => {
    const resolve = assetsStore.assetDataByAddress as (addr?: string) => Nullable<RegisteredAccountAsset>;
    return resolve(address);
  };

  const filterAssetsList = <T extends AccountAsset | RegisteredAccountAsset>(
    assets: readonly T[],
    queryValue: string,
    searchOptions?: AssetSearchOptions
  ): T[] => {
    const sorted = assets.slice().sort((a, b) => compareByBalance(a, b));
    return filterAssetsByQuery(sorted, queryValue, searchOptions);
  };

  return {
    search,
    accountAssets,
    sortedAccountAssets,
    filteredAccountAssets,
    registeredAssets,
    filteredRegisteredAssets,
    getAssetsWithBalances,
    getAssetByAddress,
    filterAssetsList,
    sortByBalance,
    isBalanceEmpty,
  };
}

export type AssetsComposable = ReturnType<typeof useAssets>;

import { FPNumber, type CodecString } from '@sora-substrate/sdk';
import { XOR } from '@sora-substrate/sdk/build/assets/consts';
import { computed } from 'vue';
import { storeToRefs } from 'pinia';

import { PageNames } from '@/consts';
import router from '@/router';
import store from '@/store';
import { useAssetsStore } from '@/stores/assets';
import { useBridgeFormStore } from '@/stores/bridge/form';

import type { RegisteredAccountAsset } from '@sora-substrate/sdk/build/assets/types';
import type { Nullable } from '@/types/common';

/**
 * Provides bridge-specific helpers that historically lived inside `BridgeMixin`.
 */
export function useBridgeCore() {
  const assetsStore = useAssetsStore();
  const bridgeFormStore = useBridgeFormStore();
  const {
    externalNativeBalance,
    assetLockedBalance,
    assetExternalMinBalance,
    outgoingMinLimit,
    outgoingMaxLimit,
    incomingMinLimit,
    soraNetworkFee,
    externalTransferFee,
  } = storeToRefs(bridgeFormStore);
  const isSoraToEvm = computed(() => store.state.bridge.isSoraToEvm);
  const asset = computed(() => store.getters.bridge.asset as Nullable<RegisteredAccountAsset>);
  const nativeToken = computed(() => store.getters.bridge.nativeToken as Nullable<RegisteredAccountAsset>);
  const sender = computed(() => store.getters.bridge.sender as string);
  const recipient = computed(() => store.getters.bridge.recipient as string);
  const isValidNetwork = computed(() => Boolean(store.getters.web3.isValidNetwork));
  const externalNetworkFee = computed(() => store.getters.bridge.externalNetworkFee as CodecString);
  const isNativeTokenSelected = computed(() => Boolean(store.getters.bridge.isNativeTokenSelected));
  const isSidechainAsset = computed(() => Boolean(store.getters.bridge.isSidechainAsset));
  const xor = computed(
    () => assetsStore.assetDataByAddress(XOR.address) as RegisteredAccountAsset
  );

  const externalTransferFeeFP = computed(() =>
    FPNumber.fromCodecValue(externalTransferFee.value, asset.value?.externalDecimals)
  );

  const nativeTokenSymbol = computed(() => nativeToken.value?.symbol ?? '');
  const nativeTokenDecimals = computed(() => nativeToken.value?.externalDecimals);

  const outgoingMaxAmount = computed<Nullable<FPNumber>>(() => {
    const limits: FPNumber[] = [];

    if (outgoingMaxLimit.value) limits.push(outgoingMaxLimit.value);
    if (isSidechainAsset.value && assetLockedBalance.value) limits.push(assetLockedBalance.value);

    if (!limits.length) return null;
    return FPNumber.min(...limits);
  });

  const outgoingMinAmount = computed<Nullable<FPNumber>>(() => {
    if (!outgoingMinLimit.value) return null;
    return outgoingMinLimit.value.add(externalTransferFeeFP.value);
  });

  const incomingMaxAmount = computed<Nullable<FPNumber>>(() => {
    if (isSidechainAsset.value) return null;
    return assetLockedBalance.value ?? null;
  });

  const getTransferMaxAmount = (isOutgoing: boolean): Nullable<FPNumber> =>
    isOutgoing ? outgoingMaxAmount.value : incomingMaxAmount.value;

  const getTransferMinAmount = (isOutgoing: boolean): Nullable<FPNumber> =>
    isOutgoing ? outgoingMinAmount.value : incomingMinLimit.value;

  const isGreaterThanTransferMaxAmount = (
    amount: string,
    currentAsset: Nullable<RegisteredAccountAsset>,
    isOutgoing: boolean,
    isRegisteredAsset = true
  ): boolean => {
    const maxAmount = getTransferMaxAmount(isOutgoing);
    if (!(currentAsset && isRegisteredAsset && maxAmount)) return false;

    const fpAmount = new FPNumber(amount);
    return FPNumber.gt(fpAmount, maxAmount);
  };

  const isLowerThanTransferMinAmount = (
    amount: string,
    currentAsset: Nullable<RegisteredAccountAsset>,
    isOutgoing: boolean,
    isRegisteredAsset = true
  ): boolean => {
    const minAmount = getTransferMinAmount(isOutgoing);
    if (!(currentAsset && isRegisteredAsset && minAmount)) return false;

    const fpAmount = new FPNumber(amount);
    return FPNumber.lt(fpAmount, minAmount);
  };

  const handleViewTransactionsHistory = () => {
    router.push({ name: PageNames.BridgeTransactionsHistory });
  };

  const navigateToBridge = () => {
    router.push({ name: PageNames.Bridge });
  };

  return {
    asset,
    nativeToken,
    sender,
    recipient,
    xor,
    isSoraToEvm,
    isValidNetwork,
    externalNetworkFee,
    externalNativeBalance,
    assetLockedBalance,
    assetExternalMinBalance,
    incomingMinLimit,
    outgoingMinLimit,
    outgoingMaxLimit,
    soraNetworkFee,
    externalTransferFee,
    externalTransferFeeFP,
    nativeTokenSymbol,
    nativeTokenDecimals,
    isNativeTokenSelected,
    isSidechainAsset,
    outgoingMaxAmount,
    outgoingMinAmount,
    incomingMaxAmount,
    getTransferMaxAmount,
    getTransferMinAmount,
    isGreaterThanTransferMaxAmount,
    isLowerThanTransferMinAmount,
    handleViewTransactionsHistory,
    navigateToBridge,
  };
}

