import {
  computed,
  nextTick,
  onBeforeUnmount,
  onMounted,
  ref,
  toValue,
  watch,
  type ComputedRef,
  type MaybeRefOrGetter,
  type Ref,
} from 'vue';

import { SortDirection } from '@soramitsu-ui/ui/types';
import { PaginationButton, type PaginationButtonValue } from '@/consts/pagination';
import type { FnWithoutArgs, Nullable } from '@/types/common';

type FilterFn<T> = (items: readonly T[], search: string) => readonly T[];

type UseExploreTableOptions<T> = {
  items: ComputedRef<readonly T[]>;
  query?: MaybeRefOrGetter<string>;
  filter?: FilterFn<T>;
  defaultOrder?: SortDirection | '';
  defaultProperty?: string;
  pageAmount?: number;
};

/**
 * Reusable replacement for the legacy Explore/Scrollable mixins.
 * Handles filtering, sorting, pagination, and scroll-sync for Sora explore tables.
 */
export function useExploreTable<T>(options: UseExploreTableOptions<T>) {
  const {
    items,
    query,
    filter,
    defaultOrder = SortDirection.DESC,
    defaultProperty = '',
    pageAmount: defaultPageAmount = 10,
  } = options;

  const order = ref<SortDirection | ''>(defaultOrder);
  const property = ref<string>(defaultProperty);
  const currentPage = ref(1);
  const pageAmount = ref(defaultPageAmount);
  const tableRef = ref<any>(null);
  const teardownScrollSync = ref<Nullable<FnWithoutArgs>>(null);

  const resolveQuery = () => (query ? toValue(query)?.toLowerCase?.().trim?.() ?? '' : '');

  const filteredItems = computed(() => {
    const search = resolveQuery();
    if (!search) return items.value;
    if (!filter) return items.value;
    return filter(items.value, search);
  });

  const isDefaultSort = computed(() => !(order.value && property.value));

  const preparedItems = computed(() => {
    if (isDefaultSort.value) return filteredItems.value;

    const isAscending = order.value === SortDirection.ASC;
    const prop = property.value as keyof T;

    return [...filteredItems.value].sort((a, b) => {
      const aValue = (a as any)[prop];
      const bValue = (b as any)[prop];

      if (aValue === bValue) return 0;

      return (isAscending ? aValue > bValue : aValue < bValue) ? 1 : -1;
    });
  });

  const total = computed(() => preparedItems.value.length);
  const lastPage = computed(() => (total.value ? Math.ceil(total.value / pageAmount.value) : 1));
  const startIndex = computed(() => (currentPage.value - 1) * pageAmount.value);

  const lastIndex = computed(() => currentPage.value * pageAmount.value);

  const tableItems = computed(() => {
    return preparedItems.value.slice(startIndex.value, lastIndex.value);
  });

  watch(
    () => resolveQuery(),
    (newValue, oldValue) => {
      if (oldValue === undefined || newValue === oldValue) return;
      currentPage.value = 1;
    }
  );

  watch(total, () => {
    if (!total.value) {
      currentPage.value = 1;
      return;
    }

    if (currentPage.value > lastPage.value) {
      currentPage.value = lastPage.value;
    }
  });

  const changeSort = ({ order: newOrder = SortDirection.DESC, property: newProperty = '' } = {}) => {
    order.value = newOrder;
    property.value = newProperty;
  };

  const handleResetSort = () => changeSort();

  const handlePaginationClick = (button: PaginationButtonValue | string) => {
    switch (button) {
      case PaginationButton.Prev:
        currentPage.value = Math.max(currentPage.value - 1, 1);
        break;
      case PaginationButton.Next:
        currentPage.value = Math.min(currentPage.value + 1, lastPage.value);
        break;
      case PaginationButton.Last:
        currentPage.value = lastPage.value;
        break;
      default:
        currentPage.value = 1;
    }
  };

  const initScrollbarSync = () => {
    teardownScrollSync.value?.();

    const tableComponent = tableRef.value;
    const elTable = tableComponent?.$refs?.table;
    const bodyWrapper = elTable?.$refs?.bodyWrapper as HTMLElement | undefined;
    const headerWrapper = elTable?.$refs?.headerWrapper as HTMLElement | undefined;

    if (!bodyWrapper || !headerWrapper) return;

    const syncScroll = () => {
      const scrollLeft = bodyWrapper.scrollLeft;
      headerWrapper.scrollLeft = scrollLeft;
      elTable.scrollPosition = scrollLeft === 0 ? 'left' : 'right';
    };

    bodyWrapper.addEventListener('scroll', syncScroll, { passive: true });
    syncScroll();

    teardownScrollSync.value = () => {
      bodyWrapper.removeEventListener('scroll', syncScroll);
    };
  };

  const refreshScrollSync = () => {
    nextTick().then(() => initScrollbarSync());
  };

  onMounted(refreshScrollSync);
  watch(tableItems, refreshScrollSync);

  onBeforeUnmount(() => {
    teardownScrollSync.value?.();
    teardownScrollSync.value = null;
  });

  return {
    order,
    property,
    currentPage,
    pageAmount,
    total,
    lastPage,
    startIndex,
    tableItems,
    tableRef: tableRef as Ref<any>,
    isDefaultSort,
    changeSort,
    handleResetSort,
    handlePaginationClick,
    initScrollbarSync,
  };
}

import { WALLET_CONSTS } from '@wallet';
import isEqual from 'lodash/fp/isEqual';
import { computed, onBeforeUnmount, ref, watch, type Ref } from 'vue';

import { useLoading } from '@/composables/useLoading';
import { debouncedInputHandler } from '@/utils';

import type { FetchVariables } from '@/types/indexers';
import type { Nullable } from '@/types/common';

type BuildDataVariablesContext = {
  fetchAmount: number;
  fetchPage: number;
};

type BuildUpdateVariablesContext = {
  intervalTimestamp: number;
};

type UseIndexerDataFetchOptions<T> = {
  parentLoading?: Ref<boolean> | (() => boolean);
  pageAmount?: number;
  fetchAmount?: number;
  updateInterval?: number;
  requestData: (variables: FetchVariables) => Promise<{ items: T[]; totalCount: number }>;
  getItemTimestamp: (item: Nullable<T>) => number;
  buildDataVariables: (context: BuildDataVariablesContext) => FetchVariables;
  buildUpdateVariables: (context: BuildUpdateVariablesContext) => FetchVariables;
};

/**
 * Composition-friendly port of `IndexerDataFetchMixin`.
 * Handles page-aware fetching, incremental updates, and loading state coordination.
 */
export function useIndexerDataFetch<T>(options: UseIndexerDataFetchOptions<T>) {
  const loadingApi = useLoading({ parentLoading: options.parentLoading });
  const pageAmount = ref(options.pageAmount ?? 5);
  const fetchAmount = ref(Math.max(options.fetchAmount ?? pageAmount.value, 1));
  const currentPage = ref(1);
  const totalCount = ref(0);
  const items = ref<readonly T[]>(Object.freeze([]));
  const updateInterval = options.updateInterval ?? 24_000;

  const safeFetchAmount = computed(() => Math.max(fetchAmount.value, 1));
  const fetchPage = computed(() => Math.max(Math.ceil((pageAmount.value * currentPage.value) / safeFetchAmount.value), 1));
  const total = computed(() => totalCount.value);
  const lastPage = computed(() => (totalCount.value ? Math.ceil(totalCount.value / pageAmount.value) : 1));
  const visibleItems = computed(() => {
    if (!items.value.length) return [];

    const offset = safeFetchAmount.value * (fetchPage.value - 1);
    const start = pageAmount.value * (currentPage.value - 1) - offset;
    const end = start + pageAmount.value;

    return items.value.slice(Math.max(start, 0), Math.max(end, 0));
  });
  const intervalTimestamp = computed(() => {
    const firstItem = items.value[0] ?? null;
    if (!firstItem) return 0;
    return Math.floor(options.getItemTimestamp(firstItem) / 1000);
  });

  let interval: Nullable<ReturnType<typeof setInterval>> = null;
  const updateItems = debouncedInputHandler(async () => {
    await updateData();
  }, 250, { leading: false });

  const resetItems = () => {
    items.value = Object.freeze([]);
    totalCount.value = 0;
  };

  const fetchData = async () => {
    await loadingApi.withLoading(async () => {
      await loadingApi.withParentLoading(async () => {
        const variables = options.buildDataVariables({
          fetchAmount: safeFetchAmount.value,
          fetchPage: fetchPage.value,
        });
        const { items: fetchedItems, totalCount: totalItems } = await options.requestData(variables);
        items.value = Object.freeze([...fetchedItems]);
        totalCount.value = totalItems;
      });
    });
  };

  const fetchDataUpdates = async () => {
    if (!intervalTimestamp.value) return;

    const variables = options.buildUpdateVariables({ intervalTimestamp: intervalTimestamp.value });
    const { items: fetchedItems, totalCount: totalItems } = await options.requestData(variables);
    if (!fetchedItems.length) return;

    items.value = Object.freeze([...fetchedItems, ...items.value].slice(0, safeFetchAmount.value));
    totalCount.value = totalCount.value + totalItems;
  };

  const resetDataSubscription = () => {
    if (interval) {
      clearInterval(interval);
    }
    interval = null;
  };

  const subscribeOnData = () => {
    resetDataSubscription();
    if (!updateInterval) return;

    interval = setInterval(() => {
      fetchDataUpdates().catch((error) => console.error(error));
    }, updateInterval);
  };

  const updateData = async () => {
    resetDataSubscription();
    await fetchData();

    if (fetchPage.value === 1) {
      subscribeOnData();
    }
  };

  watch(
    fetchPage,
    () => {
      updateItems();
    },
    { immediate: true }
  );

  const checkTriggerUpdate = (current: unknown, previous: unknown) => {
    if (!isEqual(current)(previous)) {
      currentPage.value = 1;
      resetItems();
      updateItems();
    }
  };

  const handlePaginationClick = (button: WALLET_CONSTS.PaginationButton) => {
    let current = 1;

    switch (button) {
      case WALLET_CONSTS.PaginationButton.Prev:
        current = currentPage.value - 1;
        break;
      case WALLET_CONSTS.PaginationButton.Next:
        current = currentPage.value + 1;
        break;
      case WALLET_CONSTS.PaginationButton.Last:
        current = lastPage.value;
        break;
      default:
        current = 1;
    }

    currentPage.value = current;
  };

  onBeforeUnmount(() => {
    resetDataSubscription();
  });

  return {
    loading: loadingApi.loading,
    pageAmount,
    fetchAmount,
    currentPage,
    total,
    lastPage,
    fetchPage,
    visibleItems,
    intervalTimestamp,
    handlePaginationClick,
    checkTriggerUpdate,
  };
}

import { delay } from '@wallet/src/util';
import { computed, ref } from 'vue';

import store from '@/store';

import type { WithConnectionApi } from '@sora-substrate/sdk';
import type { Ref } from 'vue';

type LoadingOptions = {
  parentLoading?: Ref<boolean> | (() => boolean);
};

type MaybePromiseFn<T> = FnWithoutArgs<T> | AsyncFnWithoutArgs<T>;

/**
 * Composition-friendly replacement for the wallet `LoadingMixin`.
 */
const importMetaMode = typeof import.meta !== 'undefined' ? (import.meta as any)?.env?.MODE : undefined;
const isTestEnvironment =
  importMetaMode === 'test' ||
  process.env.NODE_ENV === 'test' ||
  process.env.VITEST === 'true';

export function useLoading(options: LoadingOptions = {}) {
  const loading = ref(false);
  const isWalletLoaded = computed(() => store.state?.settings?.isWalletLoaded ?? true);
  const parentLoading = options.parentLoading;

  const resolveParentLoading = (): boolean => {
    if (!parentLoading) return false;
    return typeof parentLoading === 'function' ? parentLoading() : parentLoading.value;
  };

  const withLoading = async <T>(handler: MaybePromiseFn<T>): Promise<T> => {
    loading.value = true;
    try {
      return await handler();
    } catch (error) {
      console.error(error);
      throw error;
    } finally {
      loading.value = false;
    }
  };

  const withApi = async <T>(handler: MaybePromiseFn<T>): Promise<T> => {
    loading.value = true;

    if (!isWalletLoaded.value) {
      if (isTestEnvironment) {
        return await withLoading(handler);
      }

      await delay();
      return await withApi(handler);
    }

    return await withLoading(handler);
  };

  const withChainApi = async <T>(apiRef: WithConnectionApi, handler: MaybePromiseFn<T>): Promise<T> => {
    loading.value = true;

    if (!apiRef.api) {
      await delay();
      return await withChainApi(apiRef, handler);
    }

    await apiRef.api.isReady;
    return await withLoading(handler);
  };

  const withParentLoading = async <T>(handler: MaybePromiseFn<T>): Promise<T> => {
    if (resolveParentLoading()) {
      await delay();
      return await withParentLoading(handler);
    }

    return await handler();
  };

  return {
    loading,
    withLoading,
    withApi,
    withChainApi,
    withParentLoading,
  };
}

export type LoadingComposable = ReturnType<typeof useLoading>;

import { PriceVariant } from '@sora-substrate/liquidity-proxy';
import { FPNumber } from '@sora-substrate/sdk';
import dayjs from 'dayjs/esm';
import { computed, nextTick, ref, watch } from 'vue';

import { LimitOrderType, ZeroStringValue } from '@/consts';
import store from '@/store';
import { useFormattedAmount } from '@/composables/useFormattedAmount';
import {
  createFillPriceHandler,
  formatOrderRows,
  runOrderBookSubscription,
  type LimitOrderForm,
  type OrderBookPriceVolumeAggregated,
} from '@/composables/useOrderBook.utils';

import type { OrderBook } from '@sora-substrate/liquidity-proxy';
import type { AccountAsset } from '@sora-substrate/sdk/build/assets/types';
import type { OrderBookDealData } from '@/types/orderBook';
import type { AsyncFnWithoutArgs, Nullable } from '@/types/common';

const ROW_HEIGHT = 24;

type SubscriptionLoaders = {
  withLoading?: (handler: AsyncFnWithoutArgs) => Promise<void>;
  withParentLoading?: (handler: AsyncFnWithoutArgs) => Promise<void>;
};

const passthroughLoader = async (handler: AsyncFnWithoutArgs): Promise<void> => {
  await handler();
};

const toBookPrecision = (value: Nullable<number>): number => {
  return (
    value
      ?.toLocaleString()
      ?.split(FPNumber.DELIMITERS_CONFIG.decimal)[1]?.length ?? 0
  );
};

const resolveNodeConnection = (): boolean => {
  const connection = (store.getters?.settings as Record<string, unknown> | undefined)?.nodeIsConnected;

  if (typeof connection === 'boolean') return connection;
  if (connection && typeof (connection as { value?: unknown }).value === 'boolean') {
    return Boolean((connection as { value?: boolean }).value);
  }

  return true;
};

export function useOrderBook(options: { maxRows?: number } = {}) {
  const maxRows = options.maxRows ?? 11;
  const formattedAmount = useFormattedAmount();

  const orderBookState = store.state.orderBook;

  const limitOrderType = computed<LimitOrderType>(() => orderBookState.limitOrderType as LimitOrderType);
  const asks = computed<OrderBookPriceVolumeAggregated[]>(() => (orderBookState.asks as OrderBookPriceVolumeAggregated[]) ?? []);
  const bids = computed<OrderBookPriceVolumeAggregated[]>(() => (orderBookState.bids as OrderBookPriceVolumeAggregated[]) ?? []);

  const orderBookGetters = store.getters?.orderBook as Record<string, unknown>;
  const walletGetter = store.getters?.wallet as Record<string, any> | undefined;

  const currentOrderBook = computed<Nullable<OrderBook>>(
    () => (orderBookGetters?.currentOrderBook as Nullable<OrderBook>) ?? null
  );
  const baseAsset = computed<Nullable<AccountAsset>>(
    () => (orderBookGetters?.baseAsset as Nullable<AccountAsset>) ?? null
  );
  const quoteAsset = computed<Nullable<AccountAsset>>(
    () => (orderBookGetters?.quoteAsset as Nullable<AccountAsset>) ?? null
  );
  const orderBookLastDeal = computed<Nullable<OrderBookDealData>>(
    () => (orderBookGetters?.orderBookLastDeal as Nullable<OrderBookDealData>) ?? null
  );
  const orderBookId = computed(() => (orderBookGetters?.orderBookId as string) ?? '');
  const deals = computed<OrderBookDealData[]>(
    () => (store.state.orderBook?.deals as OrderBookDealData[]) ?? []
  );
  const side = computed<PriceVariant>(() => store.state.orderBook?.side ?? PriceVariant.Buy);

  const setSide = (next: PriceVariant) => {
    store.commit.orderBook?.setSide?.(next);
  };

  const exchangeRate = computed<number>(() => {
    const fromGetter = walletGetter?.settings?.exchangeRate;
    if (typeof fromGetter === 'number') return fromGetter;
    const fromState = store.state.wallet?.settings?.exchangeRate;
    return typeof fromState === 'number' ? fromState : 1;
  });

  const currencySymbol = computed<string>(() => {
    const fromGetter = walletGetter?.settings?.currencySymbol;
    if (typeof fromGetter === 'string') return fromGetter;
    const fromState = store.state.wallet?.settings?.currencySymbol;
    return typeof fromState === 'string' ? fromState : '';
  });

  const nodeIsConnected = ref(resolveNodeConnection());

  const averagePrice = computed<Nullable<FPNumber>>(() => {
    const firstAsk = asks.value?.[0]?.[0];
    const firstBid = bids.value?.[0]?.[0];
    return firstAsk ?? firstBid ?? null;
  });

  const averagePricePrecision = computed<number | undefined>(() => {
    const price = averagePrice.value;
    if (!price) return undefined;

    let result = price;
    let max = FPNumber.ONE;

    if (price.isLessThan(FPNumber.ONE)) {
      const order = new FPNumber(0.1);
      max = order;
      while (result.isLessThan(FPNumber.ONE)) {
        result = price.div(max);
        if (result.isGreaterThanOrEqualTo(FPNumber.ONE)) break;
        max = max.mul(order);
      }
    } else if (price.isGreaterThan(FPNumber.TEN)) {
      const order = FPNumber.TEN;
      max = order;
      while (result.isGreaterThan(FPNumber.ONE)) {
        result = price.div(max);
        if (result.isLessThan(FPNumber.TEN)) break;
        max = max.mul(order);
      }
    }

    return max.toNumber();
  });

  const selectedStep = ref('');

  watch(
    currentOrderBook,
    (next) => {
      selectedStep.value = next?.tickSize?.toString() ?? '';
    },
    { immediate: true, deep: true }
  );

  const steps = computed<string[]>(() => {
    const precision = averagePricePrecision.value;
    const tickSize = currentOrderBook.value?.tickSize;
    if (!(precision && tickSize)) return [];

    const values: string[] = [];
    const min = tickSize;
    const max = new FPNumber(precision);

    for (let inBetweenStep = max; inBetweenStep.isGreaterThanOrEqualTo(min); ) {
      values.push(inBetweenStep.toString());
      inBetweenStep = inBetweenStep.div(FPNumber.TEN);
    }

    return values.slice(-6);
  });

  watch(
    steps,
    (options) => {
      if (!options.length) {
        return;
      }

      if (!options.includes(selectedStep.value)) {
        selectedStep.value = options[options.length - 1];
      }
    },
    { immediate: true }
  );

  const bookPrecision = computed(() => toBookPrecision(currentOrderBook.value?.tickSize));
  const amountPrecision = computed(() => toBookPrecision(currentOrderBook.value?.stepLotSize));

  const formatOrders = (items: OrderBookPriceVolumeAggregated[]) =>
    formatOrderRows({
      orders: items,
      tickSize: currentOrderBook.value?.tickSize ?? 0,
      stepLotSize: currentOrderBook.value?.stepLotSize ?? 0,
      selectedStep: selectedStep.value,
    });

  const asksFormatted = computed<LimitOrderForm[]>(() => formatOrders(asks.value ?? []));
  const bidsFormatted = computed<LimitOrderForm[]>(() => formatOrders(bids.value ?? []));

  const sellOrders = computed<LimitOrderForm[]>(() => asksFormatted.value.slice(-maxRows));
  const buyOrders = computed<LimitOrderForm[]>(() => bidsFormatted.value.slice(0, maxRows));

  const sellMarginStyle = computed(() => {
    const margin = Math.max(maxRows - asksFormatted.value.length, 0);
    return `height: ${margin * ROW_HEIGHT}px`;
  });

  const barStyle = (filled?: number): string => `width: ${(filled ?? 0).toString()}%`;
  const showAggregationOptions = computed(() => Boolean(asksFormatted.value.length && bidsFormatted.value.length));
  const isMarketOrder = computed(() => limitOrderType.value === LimitOrderType.market);

  const lastDealTrendsUp = computed(() => orderBookLastDeal.value?.side === PriceVariant.Buy);
  const trendIcon = computed(() =>
    lastDealTrendsUp.value ? 'arrows-arrow-bold-top-24' : 'arrows-arrow-bold-bottom-24'
  );
  const lastDealPrice = computed(() => orderBookLastDeal.value?.price ?? FPNumber.ZERO);
  const lastPriceFormatted = computed(() => lastDealPrice.value.toLocaleString());

  const fiatValue = computed(() => {
    if (!quoteAsset.value) return ZeroStringValue;
    const fiatAmount = formattedAmount.getFiatAmount(lastDealPrice.value.toString(), quoteAsset.value) ?? '0';
    const converted = new FPNumber(fiatAmount).mul(exchangeRate.value).toLocaleString();
    return converted ? `${currencySymbol.value}${converted}` : ZeroStringValue;
  });

  const trendClass = computed(() =>
    ['stock-book-delimiter', lastDealTrendsUp.value ? 'stock-book-delimiter--up' : 'stock-book-delimiter--down'].join(
      ' '
    )
  );

  const fillPriceHandler = computed(() =>
    createFillPriceHandler(limitOrderType.value, {
      setSide: (side) => store.commit.orderBook?.setSide?.(side),
      setQuoteValue: (value) => store.commit.orderBook?.setQuoteValue?.(value),
    })
  );

  const fillPrice = (price: string, side: PriceVariant): void => {
    fillPriceHandler.value(price, side);
  };

  const subscribeToOrderBook = async (loaders: SubscriptionLoaders = {}): Promise<void> => {
    if (!orderBookId.value) return;

    const withLoading = loaders.withLoading ?? passthroughLoader;
    const withParentLoading = loaders.withParentLoading ?? passthroughLoader;

    await runOrderBookSubscription({
      withLoading,
      withParentLoading,
      subscribe: async () => {
        await store.dispatch.orderBook?.subscribeToBidsAndAsks?.();
      },
    });
  };

  const unsubscribeFromOrderBook = async (): Promise<void> => {
    await store.dispatch.orderBook?.unsubscribeFromBidsAndAsks?.();
  };

  const watchOrderBookSubscription = (loaders: SubscriptionLoaders = {}) => {
    return watch(
      [orderBookId, nodeIsConnected],
      async ([id, connected]) => {
        if (!id || !connected) {
          await unsubscribeFromOrderBook();
          return;
        }

        await subscribeToOrderBook(loaders);
      },
      { immediate: true }
    );
  };

  watch(
    () => (store.getters?.settings as Record<string, unknown> | undefined)?.nodeIsConnected,
    async () => {
      nodeIsConnected.value = resolveNodeConnection();
      await nextTick();
    }
  );

  const isBookPrecisionEqual = (precision: string): boolean => {
    return precision === (currentOrderBook.value?.tickSize?.toString() ?? '');
  };

  const setSelectedStep = (value: string) => {
    selectedStep.value = value;
  };

  const completedOrders = computed(() =>
    deals.value.map((deal) => {
      const timestamp = deal.timestamp ?? Date.now();
      const date = dayjs(timestamp);
      const time = date.format('M/DD HH:mm:ss');
      const amountSymbol = baseAsset.value?.symbol ?? '';
      const priceSymbol = quoteAsset.value?.symbol ?? '';

      const amount = `${deal.amount.toLocaleString()} ${amountSymbol}`;
      const price = `${deal.price.toLocaleString()} ${priceSymbol}`;
      const isBuy = deal.side === PriceVariant.Buy;

      return { time, amount, price, isBuy };
    })
  );

  return {
    baseAsset,
    quoteAsset,
    asks,
    bids,
    asksFormatted,
    bidsFormatted,
    sellOrders,
    buyOrders,
    sellMarginStyle,
    barStyle,
    showAggregationOptions,
    isMarketOrder,
    steps,
    selectedStep,
    setSelectedStep,
    bookPrecision,
    amountPrecision,
    lastDealTrendsUp,
    trendIcon,
    trendClass,
    lastPriceFormatted,
    fiatValue,
    fillPrice,
    subscribeToOrderBook,
    unsubscribeFromOrderBook,
    watchOrderBookSubscription,
    orderBookId,
    limitOrderType,
    side,
    setSide,
    completedOrders,
    PriceVariant,
  };
}

export type OrderBookComposable = ReturnType<typeof useOrderBook>;

