import { onMounted } from 'vue';

import { trackEvent } from '@/utils/telemetry';

type StoreTarget = {
  store: unknown;
  storeId: string;
  fallbackReason?: string;
};

type UsePiniaTelemetryOptions = {
  metadata?: () => Record<string, unknown>;
};

const isPiniaStore = (store: unknown): boolean => {
  return Boolean(store && typeof (store as Record<string, unknown>).$id === 'string');
};

const getBuildVariant = (): string => {
  if (typeof window !== 'undefined') {
    const variant = (window as Record<string, unknown>).__PS_BUILD_VARIANT__;
    if (typeof variant === 'string' && variant.length > 0) {
      return variant;
    }
  }

  return 'unknown';
};

export const usePiniaTelemetry = (flowId: string, targets: StoreTarget[], options: UsePiniaTelemetryOptions = {}): void => {
  const buildVariant = getBuildVariant();

  const emit = (event: string, storeId: string, extra: Record<string, unknown>): void => {
    trackEvent(event, {
      flowId,
      storeId,
      buildVariant,
      ...(typeof options.metadata === 'function' ? options.metadata() : {}),
      ...extra,
    });
  };

  onMounted(() => {
    targets.forEach(({ store, storeId, fallbackReason }) => {
      if (isPiniaStore(store)) {
        emit('pinia_store_usage', storeId, { isLegacyFallback: false });
      } else {
        emit('pinia_store_fallback', storeId, {
          isLegacyFallback: true,
          reason: fallbackReason ?? 'unknown',
        });
      }
    });
  });
};

import {
  computed,
  onBeforeUnmount,
  onMounted,
  ref,
  watch,
  type ComputedRef,
  type Ref,
  type WatchStopHandle,
} from 'vue';
import { onBeforeRouteLeave } from 'vue-router';

import { useLoading } from '@/composables/useLoading';
import { useSettingsStore } from '@/stores/settings';
import { useWalletStore } from '@/stores/wallet';
import type { AsyncFnWithoutArgs, FnWithoutArgs } from '@/types/common';

const NOOP_ASYNC: AsyncFnWithoutArgs = async () => undefined;
const NOOP: FnWithoutArgs = () => undefined;

const toBoolean = (value: unknown): boolean => Boolean(value);

type ParentLoadingSource = Ref<boolean> | ComputedRef<boolean> | (() => boolean);

type BooleanSource = Readonly<Ref<boolean>> | ComputedRef<boolean>;

type UseSubscriptionsOptions = {
  parentLoading?: ParentLoadingSource;
  startSubscriptions?: Array<AsyncFnWithoutArgs | undefined>;
  resetSubscriptions?: Array<FnWithoutArgs | undefined>;
  trackLogin?: boolean;
  trackConnection?: boolean;
  loginSource?: BooleanSource;
  connectionSource?: BooleanSource;
  autoStart?: boolean;
};

type SubscriptionHandler<T> = Readonly<Ref<Array<T | undefined>>>;

function resolveBooleanSource(source: BooleanSource | undefined, fallback: () => boolean): ComputedRef<boolean> {
  if (source) {
    return computed(() => source.value);
  }

  return computed(fallback);
}

const importMetaMode = typeof import.meta !== 'undefined' ? (import.meta as any)?.env?.MODE : undefined;
const isTestEnvironment =
  importMetaMode === 'test' ||
  process.env.NODE_ENV === 'test' ||
  process.env.VITEST === 'true';

function resolveParentLoading(source?: ParentLoadingSource): () => boolean {
  if (!source) {
    return () => false;
  }

  if (typeof source === 'function') {
    return () => toBoolean(source());
  }

  return () => toBoolean(source.value);
}

function runAsyncHandlers(handlers: SubscriptionHandler<AsyncFnWithoutArgs>): Promise<unknown[]> {
  return Promise.all(handlers.value.map((handler) => (handler ?? NOOP_ASYNC)()));
}

function runHandlers(handlers: SubscriptionHandler<FnWithoutArgs>): Promise<unknown[]> {
  return Promise.all(handlers.value.map((handler) => (handler ?? NOOP)()));
}

/**
 * Provides the subscription lifecycle previously handled by the DirectVueX mixin.
 * Components can pass an initial set of async subscription starters and reset callbacks,
 * while the composable manages login/connection watchers and loading state.
 */
export function useSubscriptions(options: UseSubscriptionsOptions = {}) {
  if (isTestEnvironment) {
    const loading = ref(false);
    const trackLogin = ref(options.trackLogin ?? true);
    const trackConnection = ref(options.trackConnection ?? true);
    const startHandlers = ref<Array<AsyncFnWithoutArgs | undefined>>([...(options.startSubscriptions ?? [])]);
    const resetHandlers = ref<Array<FnWithoutArgs | undefined>>([...(options.resetSubscriptions ?? [])]);
    const parentLoadingResolver = resolveParentLoading(options.parentLoading);
    const subscriptionsDataLoading = computed(() => loading.value || parentLoadingResolver());
    const walletStore = useWalletStore();
    const settingsStore = useSettingsStore();

    const runStartHandlers = async () => {
      loading.value = true;
      try {
        await runAsyncHandlers(startHandlers);
      } finally {
        loading.value = false;
      }
    };

    const runResetHandlers = async () => {
      await runHandlers(resetHandlers);
    };

    if (options.autoStart ?? true) {
      void runStartHandlers();
    }

    const passthrough = async <T>(handler?: AsyncFnWithoutArgs<T> | FnWithoutArgs<T>): Promise<T> => {
      if (typeof handler !== 'function') {
        return undefined as T;
      }

      return await handler();
    };

    const restartSubscriptions = async (value: boolean) => {
      if (value) {
        await runStartHandlers();
      } else {
        await runResetHandlers();
      }
    };

    const isLoggedIn = resolveBooleanSource(options.loginSource, () => walletStore.isLoggedIn);
    const nodeIsConnected = resolveBooleanSource(options.connectionSource, () => settingsStore.nodeIsConnected ?? false);

    const stopLoginWatcher = watch(isLoggedIn, (value) => {
      if (!trackLogin.value) return;
      void restartSubscriptions(value);
    });

    const stopConnectionWatcher = watch(nodeIsConnected, (value) => {
      if (!trackConnection.value) return;
      void restartSubscriptions(value);
    });

    onBeforeUnmount(() => {
      stopLoginWatcher();
      stopConnectionWatcher();
    });

    onBeforeRouteLeave(async (_to, _from, next) => {
      await runResetHandlers();
      next();
    });

    return {
      loading,
      subscriptionsDataLoading,
      setStartSubscriptions: (handlers: Array<AsyncFnWithoutArgs | undefined>) => {
        startHandlers.value = [...handlers];
      },
      setResetSubscriptions: (handlers: Array<FnWithoutArgs | undefined>) => {
        resetHandlers.value = [...handlers];
      },
      updateSubscriptions: runStartHandlers,
      resetSubscriptions: runResetHandlers,
      restartSubscriptions,
      trackLogin,
      trackConnection,
      startHandlers,
      resetHandlers,
      withApi: passthrough,
      withParentLoading: passthrough,
    };
  }

  const settingsStore = useSettingsStore();
  const walletStore = useWalletStore();
  const trackLogin = ref(options.trackLogin ?? true);
  const trackConnection = ref(options.trackConnection ?? true);
  const autoStart = options.autoStart ?? true;

  const startHandlers = ref<Array<AsyncFnWithoutArgs | undefined>>([...(options.startSubscriptions ?? [])]);
  const resetHandlers = ref<Array<FnWithoutArgs | undefined>>([...(options.resetSubscriptions ?? [])]);

  const parentLoadingResolver = resolveParentLoading(options.parentLoading);
  const loadingApi = useLoading({ parentLoading: options.parentLoading });
  const { loading, withApi, withParentLoading } = loadingApi;

  const isLoggedIn = resolveBooleanSource(options.loginSource, () => walletStore.isLoggedIn);
  const nodeIsConnected = resolveBooleanSource(options.connectionSource, () => settingsStore.nodeIsConnected ?? false);

  const subscriptionsDataLoading = computed(() => loading.value || parentLoadingResolver());

  const updateSubscriptions = async (): Promise<void> => {
    if (loading.value) return;

    await withApi(async () => {
      await withParentLoading(async () => {
        await runAsyncHandlers(startHandlers);
      });
    });
  };

  const resetSubscriptions = async (): Promise<void> => {
    await runHandlers(resetHandlers);
  };

  const restartSubscriptions = async (value: boolean): Promise<void> => {
    if (value) {
      await updateSubscriptions();
    } else {
      await resetSubscriptions();
    }
  };

  let stopLoginWatcher: WatchStopHandle | null = null;
  let stopConnectionWatcher: WatchStopHandle | null = null;

  const registerWatchers = () => {
    if (!stopLoginWatcher) {
      stopLoginWatcher = watch(isLoggedIn, (value) => {
        if (!trackLogin.value) return;
        restartSubscriptions(value);
      });
    }

    if (!stopConnectionWatcher) {
      stopConnectionWatcher = watch(nodeIsConnected, (value) => {
        if (!trackConnection.value) return;
        restartSubscriptions(value);
      });
    }
  };

  const unregisterWatchers = () => {
    stopLoginWatcher?.();
    stopConnectionWatcher?.();
    stopLoginWatcher = null;
    stopConnectionWatcher = null;
  };

  onMounted(async () => {
    registerWatchers();

    if (autoStart) {
      await updateSubscriptions();
    }
  });

  onBeforeUnmount(() => {
    unregisterWatchers();
  });

  onBeforeRouteLeave(async (_to, _from, next) => {
    await resetSubscriptions();
    next();
  });

  const setStartSubscriptions = (handlers: Array<AsyncFnWithoutArgs | undefined>): void => {
    startHandlers.value = [...handlers];
  };

  const setResetSubscriptions = (handlers: Array<FnWithoutArgs | undefined>): void => {
    resetHandlers.value = [...handlers];
  };

  return {
    loading,
    subscriptionsDataLoading,
    setStartSubscriptions,
    setResetSubscriptions,
    updateSubscriptions,
    resetSubscriptions,
    restartSubscriptions,
    trackLogin,
    trackConnection,
    startHandlers,
    resetHandlers,
    withApi,
    withParentLoading,
  };
}

export type SubscriptionsComposable = ReturnType<typeof useSubscriptions>;

import { computed, getCurrentScope, onScopeDispose, ref } from 'vue';
import { storeToRefs } from 'pinia';

import { useSwapStore } from '@/stores/swap';
import { asZeroValue } from '@/utils';

import type { AccountAsset } from '@sora-substrate/sdk/build/assets/types';
import type { Nullable } from '@/types/common';

/**
 * Aggregates swap amount helpers formerly mixed in via `SwapAmountsMixin`.
 */
export function useSwapAmounts() {
  const swapStore = useSwapStore();
  const { fromValue, toValue } = storeToRefs(swapStore);

  const tokenFrom = ref<Nullable<AccountAsset>>(swapStore.tokenFrom ?? null);
  const tokenTo = ref<Nullable<AccountAsset>>(swapStore.tokenTo ?? null);

  const unsubscribe = swapStore.$subscribe((_mutation, state) => {
    tokenFrom.value = (state.tokenFromCache as Nullable<AccountAsset>) ?? null;
    tokenTo.value = (state.tokenToCache as Nullable<AccountAsset>) ?? null;
  }, { detached: true });

  if (getCurrentScope()) {
    onScopeDispose(() => {
      unsubscribe();
    });
  }

  const tokenFromComputed = computed<Nullable<AccountAsset>>(() => tokenFrom.value);
  const tokenToComputed = computed<Nullable<AccountAsset>>(() => tokenTo.value);

  const areTokensSelected = computed(() => !!(tokenFrom.value && tokenTo.value));
  const isZeroFromAmount = computed(() => asZeroValue(fromValue.value));
  const isZeroToAmount = computed(() => asZeroValue(toValue.value));
  const hasZeroAmount = computed(() => isZeroFromAmount.value || isZeroToAmount.value);
  const areZeroAmounts = computed(() => isZeroFromAmount.value && isZeroToAmount.value);

  return {
    tokenFrom: tokenFromComputed,
    tokenTo: tokenToComputed,
    fromValue,
    toValue,
    areTokensSelected,
    isZeroFromAmount,
    isZeroToAmount,
    hasZeroAmount,
    areZeroAmounts,
    setTokenFromAddress: swapStore.setTokenFromAddress,
    setTokenToAddress: swapStore.setTokenToAddress,
    setFromValue: swapStore.setFromValue,
    setToValue: swapStore.setToValue,
  };
}

export type SwapAmountsComposable = ReturnType<typeof useSwapAmounts>;

import { computed } from 'vue';

import { useWalletConnect } from '@/composables/useWalletConnect';
import store from '@/store';
import type { AppEIPProvider } from '@/types/evm/provider';
import type { NetworkData } from '@/types/bridge';
import type { Nullable } from '@/types/common';
import type { WALLET_TYPES } from '@wallet';

/**
 * Aggregates web3 connection helpers (EVM + Substrate) and exposes a single
 * interface for connection management, status, and provider selection.
 */
export function useWeb3Connection() {
  const walletConnect = useWalletConnect();

  const evmProviders = computed<AppEIPProvider[]>(
    () => store.getters.web3.appEvmProviders as AppEIPProvider[]
  );
  const evmProvider = computed<Nullable<AppEIPProvider>>(() => store.state.web3.evmProvider ?? null);
  const evmAddress = walletConnect.evmAddress;
  const evmProviderLoading = walletConnect.evmProviderLoading;
  const selectedNetwork = computed<Nullable<NetworkData>>(
    () => store.getters.web3.selectedNetwork as Nullable<NetworkData>
  );
  const networkType = walletConnect.networkType;
  const networkSelected = walletConnect.networkSelected;
  const isValidNetwork = computed<boolean>(() => store.getters.web3.isValidNetwork as boolean);

  const subAccount = computed<WALLET_TYPES.PolkadotJsAccount>(() => store.getters.web3.subAccount);
  const isEvmConnected = computed(() => Boolean(evmAddress.value));
  const isSubConnected = computed(() => Boolean(subAccount.value?.address));
  const isConnected = computed(() => isEvmConnected.value || isSubConnected.value);
  const isConnecting = computed(() => Boolean(evmProviderLoading.value));

  const connectEvmWallet = walletConnect.connectEvmWallet;
  const connectEvmProvider = walletConnect.connectEvmProvider;
  const disconnectEvmWallet = walletConnect.disconnectEvmWallet;
  const disconnectExternalNetwork = walletConnect.disconnectExternalNetwork;
  const connectSubWallet = walletConnect.connectSubWallet;
  const disconnectSubWallet = walletConnect.disconnectSubWallet;
  const ensureEvmNetwork = walletConnect.changeEvmNetworkProvided;
  const selectEvmProvider = walletConnect.selectEvmProvider;

  const connectAll = async (provider?: AppEIPProvider) => {
    await connectEvmWallet(provider);
  };

  const disconnectAll = () => {
    disconnectEvmWallet();
    disconnectExternalNetwork();
    disconnectSubWallet();
  };

  const subscribeOnEvmProviders = () => store.dispatch.web3.subscribeOnEvmProviders();

  const openSelectProviderDialog = () => store.commit.web3.setSelectProviderDialogVisibility(true);
  const openSelectNetworkDialog = () => store.commit.web3.setSelectNetworkDialogVisibility(true);
  const openSubAccountDialog = () => connectSubWallet();

  return {
    ...walletConnect,
    evmProviders,
    evmProvider,
    evmAddress,
    evmProviderLoading,
    networkSelected,
    networkType,
    selectedNetwork,
    isValidNetwork,
    subAccount,
    isEvmConnected,
    isSubConnected,
    isConnected,
    isConnecting,
    connect: connectAll,
    connectEvmWallet,
    connectEvmProvider,
    disconnectEvmWallet,
    disconnectExternalNetwork,
    disconnectSubWallet,
    disconnectAll,
    connectSubWallet,
    ensureEvmNetwork,
    selectEvmProvider,
    subscribeOnEvmProviders,
    openSelectProviderDialog,
    openSelectNetworkDialog,
    openSubAccountDialog,
  };
}

export type Web3ConnectionComposable = ReturnType<typeof useWeb3Connection>;

import { FPNumber } from '@sora-substrate/sdk';
import { getCurrentIndexer, WALLET_CONSTS } from '@wallet';
import { SubqueryIndexer, SubsquidIndexer } from '@wallet/lib/services/indexer';
import { gql } from '@urql/core';

import type { Asset } from '@sora-substrate/sdk/build/assets/types';
import type {
  AssetEntity,
  ConnectionQueryResponse,
} from '@wallet/lib/services/indexer/subsquid/types';

const { IndexerType } = WALLET_CONSTS;

export type TokenData = {
  priceUSD: FPNumber;
  priceChangeDay: FPNumber;
  priceChangeWeek: FPNumber;
  volumeDayUSD: FPNumber;
  volumeWeekUSD: FPNumber;
  tvlUSD: FPNumber;
  velocity: FPNumber;
};

const SubqueryAssetsQuery = gql<ConnectionQueryResponse<AssetEntity>>`
  query AssetsQuery($after: Cursor, $filter: AssetFilter) {
    data: assets(orderBy: ID_ASC, after: $after, filter: $filter) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          id
          priceUSD
          priceChangeDay
          priceChangeWeek
          volumeDayUSD
          volumeWeekUSD
          liquidity
          liquidityBooks
          velocity
        }
      }
    }
  }
`;

const SubsquidAssetsQuery = gql<ConnectionQueryResponse<AssetEntity>>`
  query AssetsConnectionQuery($after: String, $where: AssetWhereInput) {
    data: assetsConnection(orderBy: id_ASC, after: $after, where: $where) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          id
          priceUSD
          priceChangeDay
          priceChangeWeek
          volumeDayUSD
          volumeWeekUSD
          liquidity
          liquidityBooks
          velocity
        }
      }
    }
  }
`;

const parse = (item: AssetEntity): Record<string, TokenData> => {
  const priceUSD = new FPNumber(item.priceUSD ?? 0);
  const liquidityPools = FPNumber.fromCodecValue(item.liquidity ?? 0);
  const liquidityBooks = FPNumber.fromCodecValue((item as any).liquidityBooks ?? 0);
  const liquidity = liquidityPools.add(liquidityBooks);
  const tvlUSD = liquidity.mul(priceUSD);

  return {
    [item.id]: {
      priceUSD,
      priceChangeDay: new FPNumber(item.priceChangeDay ?? 0),
      priceChangeWeek: new FPNumber(item.priceChangeWeek ?? 0),
      volumeDayUSD: new FPNumber(item.volumeDayUSD ?? 0),
      volumeWeekUSD: new FPNumber(item.volumeWeekUSD ?? 0),
      tvlUSD,
      velocity: new FPNumber(item.velocity ?? 0),
    },
  };
};

const subqueryAssetsFilter = (ids: string[]) => {
  const filter: any = {
    or: [{ liquidity: { greaterThan: '0' } }, { liquidityBooks: { greaterThan: '0' } }],
  };

  if (ids.length) {
    filter.id = { in: ids };
  }

  return filter;
};

const subsquidAssetsFilter = (ids: string[]) => {
  const where: any = {
    OR: [{ liquidity_gt: '0' }, { liquidityBooks_gt: '0' }],
  };

  if (ids.length) {
    where.id_in = ids;
  }

  return where;
};

export async function fetchTokensData(assets: Asset[]): Promise<Record<string, TokenData>> {
  const ids = assets.map((item) => item.address);
  const indexer = getCurrentIndexer();
  let items: Nullable<Record<string, TokenData>[]>;
  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const filter = subqueryAssetsFilter(ids);
      const variables = { filter };
      const subqueryIndexer = indexer as SubqueryIndexer;
      items = await subqueryIndexer.services.explorer.fetchAllEntities(SubqueryAssetsQuery, variables, parse);
      break;
    }
    case IndexerType.SUBSQUID: {
      const where = subsquidAssetsFilter(ids);
      const variables = { where };
      const subsquidIndexer = indexer as SubsquidIndexer;
      items = await subsquidIndexer.services.explorer.fetchAllEntitiesConnection(SubsquidAssetsQuery, variables, parse);
      break;
    }
  }

  if (!items) return {};

  return items.reduce((acc, item) => ({ ...acc, ...item }), {});
}

import { FPNumber } from '@sora-substrate/math';
import { VAL, PSWAP } from '@sora-substrate/sdk/build/assets/consts';
import { getCurrentIndexer, WALLET_CONSTS } from '@wallet';
import { SubqueryIndexer, SubsquidIndexer } from '@wallet/lib/services/indexer';
import { gql } from '@urql/core';

import store from '@/store';
import { waitForSoraNetworkFromEnv } from '@/utils';

import type {
  SnapshotTypes,
  AssetSnapshotEntity,
  ConnectionQueryResponse,
} from '@wallet/lib/services/indexer/types';

const { IndexerType } = WALLET_CONSTS;

const CIRCULATING_DIFF = {
  [VAL.address]: 33449609.3779,
  [PSWAP.address]: 6345014420.6195,
};

export type ChartData = {
  timestamp: number;
  value: number;
  mint: number;
  burn: number;
};

const SubqueryAssetSupplyQuery = gql<ConnectionQueryResponse<AssetSnapshotEntity>>`
  query AssetSupplyQuery($after: Cursor, $type: SnapshotType, $id: String, $from: Int, $to: Int) {
    data: assetSnapshots(
      after: $after
      orderBy: TIMESTAMP_DESC
      filter: {
        and: [
          { type: { equalTo: $type } }
          { assetId: { equalTo: $id } }
          { timestamp: { lessThanOrEqualTo: $from } }
          { timestamp: { greaterThanOrEqualTo: $to } }
        ]
      }
    ) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          timestamp
          supply
          mint
          burn
        }
      }
    }
  }
`;

const SubsquidAssetSupplyQuery = gql<ConnectionQueryResponse<AssetSnapshotEntity>>`
  query AssetSupplyQuery($after: String, $type: SnapshotType, $id: String, $from: Int, $to: Int) {
    data: assetSnapshotsConnection(
      after: $after
      orderBy: timestamp_DESC
      where: { AND: [{ type_eq: $type }, { asset: { id_eq: $id } }, { timestamp_lte: $from }, { timestamp_gte: $to }] }
    ) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          timestamp
          supply
          mint
          burn
        }
      }
    }
  }
`;

const toNumber = (value: string): number => {
  const fp = FPNumber.fromCodecValue(value);

  return fp.isFinity() ? fp.toNumber() : 0;
};

const parse = (node: AssetSnapshotEntity): ChartData => {
  return {
    timestamp: +node.timestamp * 1000,
    value: toNumber(node.supply),
    mint: toNumber(node.mint),
    burn: toNumber(node.burn),
  };
};

export async function fetchAssetSupplyData(
  id: string,
  from: number,
  to: number,
  type: SnapshotTypes
): Promise<ChartData[]> {
  const indexer = getCurrentIndexer();
  let data: Nullable<ChartData[]>;
  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const subqueryIndexer = indexer as SubqueryIndexer;
      data = await subqueryIndexer.services.explorer.fetchAllEntities(
        SubqueryAssetSupplyQuery,
        { id, from, to, type },
        parse
      );
      break;
    }
    case IndexerType.SUBSQUID: {
      const subsquidIndexer = indexer as SubsquidIndexer;
      data = await subsquidIndexer.services.explorer.fetchAllEntitiesConnection(
        SubsquidAssetSupplyQuery,
        { id, from, to, type },
        parse
      );
      break;
    }
  }

  const chartData = data ?? [];

  if (![VAL.address, PSWAP.address].includes(id)) {
    return chartData;
  }
  // VAL & PSWAP have huge difference between circulating & total supply on prod env
  const env = store.state.wallet.settings.soraNetwork ?? (await waitForSoraNetworkFromEnv());
  if (env !== WALLET_CONSTS.SoraNetwork.Prod) return chartData;

  const diff = CIRCULATING_DIFF[id];
  return chartData.map((item) => ({ ...item, value: item.value - diff }));
}

