        and: [
          { blockHeight: { greaterThanOrEqualTo: $start } }
          { blockHeight: { lessThanOrEqualTo: $end } }
          {
            or: [
              {
                and: [
                  { data: { contains: { to: $account } } }
                  { module: { equalTo: "bridgeMultisig" } }
                  { method: { equalTo: "asMulti" } }
                ]
              }
              {
                and: [
                  { address: { equalTo: $account } }
                  { module: { equalTo: "ethBridge" } }
                  { method: { equalTo: "transferToSidechain" } }
                ]
              }
            ]
          }
        ]
      }
    ) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          data
        }
      }
    }
  }
`;

const SubsquidBridgeQuery = gql<ConnectionQueryResponse<HistoryElement>>`
  query BridgeQuery($start: Int = 0, $end: Int = 0, $account: String = "", $after: String = null, $first: Int = 100) {
    data: historyElementsConnection(
      orderBy: id_ASC
      first: $first
      after: $after
      where: {
        AND: [
          { blockHeight_gte: $start }
          { blockHeight_lte: $end }
          {
            OR: [
              {
                AND: [
                  { data_jsonContains: { to: $account } }
                  { module_eq: "bridgeMultisig" }
                  { method_eq: "asMulti" }
                ]
              }
              { AND: [{ address_eq: $account }, { module_eq: "ethBridge" }, { method_eq: "transferToSidechain" }] }
            ]
          }
        ]
      }
    ) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          data
        }
      }
    }
  }
`;

const parseBridgeData = (item: HistoryElement): BridgeData => {
  const data = item.data as BridgeHistoryElement;

  return {
    amount: new FPNumber(data.amount),
    assetId: data.assetId,
    type: (data as HistoryElementEthBridgeOutgoing).sidechainAddress ? 'outgoing' : 'incoming',
  };
};

export async function fetchBridgeData(start: number, end: number, account: string): Promise<BridgeData[]> {
  const indexer = getCurrentIndexer();
  const variables = { start, end, account };

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const subqueryIndexer = indexer as SubqueryIndexer;
      const items = await subqueryIndexer.services.explorer.fetchAllEntities(
        SubqueryBridgeQuery,
        variables,
        parseBridgeData
      );
      return items ?? [];
    }
    case IndexerType.SUBSQUID: {
      const subsquidIndexer = indexer as SubsquidIndexer;
      const items = await subsquidIndexer.services.explorer.fetchAllEntitiesConnection(
        SubsquidBridgeQuery,
        variables,
        parseBridgeData
      );
      return items ?? [];
    }
  }

  return [];
}

const getSubqueryCountQuery = (filter: string) => gql<ConnectionQueryResponse<CountResponse>>`
  query CountQuery($start: Int = 0, $end: Int = 0, $account: String = "", $after: Cursor = "", $first: Int = 100) {
    data: historyElements(
      first: $first
      after: $after
      filter: {
        and: [
          { blockHeight: { greaterThanOrEqualTo: $start } }
          { blockHeight: { lessThanOrEqualTo: $end } }
          { address: { equalTo: $account } }
          ${filter}
        ]
      }
    ) {
      totalCount
    }
  }
`;

const getSubsquidCountQuery = (filter: string) => gql<ConnectionQueryResponse<CountResponse>>`
  query CountQuery($start: Int = 0, $end: Int = 0, $account: String = "", $after: String = null, $first: Int = 100) {
    data: historyElementsConnection(
      orderBy: id_ASC
      first: $first
      after: $after
      where: {
        AND: [
          { blockHeight_gte: $start }
          { blockHeight_lte: $end }
          { address_eq: $account }
          ${filter}
        ]
      }
    ) {
      totalCount
    }
  }
`;

const CountFilers = {
  [IndexerType.SUBQUERY]: {
    [CountType.Swap]: `{ module: { equalTo: "liquidityProxy" } } { method: { equalTo: "swap" } }`,
    [CountType.PoolDeposit]: `{ module: { equalTo: "poolXYK" } } { method: { equalTo: "depositLiquidity" } }`,
    [CountType.PoolWithdraw]: `{ module: { equalTo: "poolXYK" } } { method: { equalTo: "withdrawLiquidity" } }`,
  },
  [IndexerType.SUBSQUID]: {
    [CountType.Swap]: `{ module_eq: "liquidityProxy" } { method_eq: "swap" }`,
    [CountType.PoolDeposit]: `{ module_eq: "poolXYK" } { method_eq: "depositLiquidity" }`,
    [CountType.PoolWithdraw]: `{ module_eq: "poolXYK" } { method_eq: "withdrawLiquidity" }`,
  },
};

export async function fetchCount(start: number, end: number, account: string, type: CountType): Promise<number> {
  const indexer = getCurrentIndexer();
  const variables = { start, end, account };
  const filter = CountFilers[indexer.type]?.[type];

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const subqueryIndexer = indexer as SubqueryIndexer;
      const response = await subqueryIndexer.services.explorer.fetchEntities(getSubqueryCountQuery(filter), variables);
      return response?.totalCount ?? 0;
    }
    case IndexerType.SUBSQUID: {
      const subsquidIndexer = indexer as SubsquidIndexer;
      const response = await subsquidIndexer.services.explorer.fetchEntitiesConnection(
        getSubsquidCountQuery(filter),
        variables
      );
      return response?.totalCount ?? 0;
    }
  }

  return 0;
}

type AccountMetaAssetVolume = {
  amount: string; // formatted NumberLike
  amountUSD: string; // formatted NumberLike
};

type AccountMetaEventCounter = {
  created: number; // count
  closed: number; // count
  amountUSD: string; // formatted NumberLike
};

type AccountMetaGovernance = {
  votes: number; // count
  amount: string; // formatted NumberLike
  amountUSD: string; // formatted NumberLike
};

type AccountMetaDeposit = {
  incomingUSD: string; // formatted NumberLike
  outgoingUSD: string; // formatted NumberLike
};

type AccountMetaEntity = {
  id: string;
  accountId: string;
  createdAtTimestamp: number;
  createdAtBlock: number;
  xorFees: AccountMetaAssetVolume;
  xorBurned: AccountMetaAssetVolume;
  xorStakingValRewards: AccountMetaAssetVolume;
  orderBook: AccountMetaEventCounter;
  vault: AccountMetaEventCounter;
  governance: AccountMetaGovernance;
  deposit: AccountMetaDeposit;
};

type AccountPointSystemEntity = {
  id: string;
  accountId: string;
  version: number;
  startedAtBlock: number;
  // points
  xorFees: AccountMetaAssetVolume;
  xorBurned: AccountMetaAssetVolume;
  xorStakingValRewards: AccountMetaAssetVolume;
  orderBook: AccountMetaEventCounter;
  vault: AccountMetaEventCounter;
  governance: AccountMetaGovernance;
  deposit: AccountMetaDeposit;
};

const SubqueryAccountMetaQuery = gql<QueryData<AccountMetaEntity>>`
  query AccountMetaQuery($id: String = "") {
    data: accountMeta(id: $id) {
      createdAtTimestamp
      createdAtBlock
      xorFees
      xorBurned
      xorStakingValRewards
      orderBook
      vault
      governance
      deposit
    }
  }
`;

const SubqueryAccountPointSystemsQuery = gql<ConnectionQueryResponse<AccountPointSystemEntity>>`
  query AccountPointSystemsQuery($id: String = "", $after: Cursor) {
    data: accountPointSystems(orderBy: ID_ASC, after: $after, filter: { accountId: { equalTo: $id } }) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          id
          accountId
          version
          startedAtBlock
          xorFees
          xorBurned
          xorStakingValRewards
          orderBook
          vault
          governance
          deposit
        }
      }
    }
  }
`;

const parseVolume = (data: AccountMetaAssetVolume | AccountMetaGovernance) => {
  return {
    amount: new FPNumber(data.amount),
    amountUSD: new FPNumber(data.amountUSD),
  };
};

const parseCounter = (data: AccountMetaEventCounter) => {
  return {
    created: new FPNumber(data.created),
    closed: new FPNumber(data.closed),
    amountUSD: new FPNumber(data.amountUSD),
  };
};

const parseAccountPoints = (item: AccountMetaEntity | AccountPointSystemEntity): AccountPointsCalculation => {
  const { xorFees, xorBurned, xorStakingValRewards, orderBook, vault, governance, deposit } = item;

  return {
    fees: parseVolume(xorFees),
    burned: parseVolume(xorBurned),
    staking: parseVolume(xorStakingValRewards),
    orderBook: parseCounter(orderBook),
    kensetsu: parseCounter(vault),
    governance: {
      votes: new FPNumber(governance.votes),
      ...parseVolume(governance),
    },
    bridge: {
      incomingUSD: new FPNumber(deposit.incomingUSD),
      outgoingUSD: new FPNumber(deposit.outgoingUSD),
    },
  };
};

const parseAccountMeta = (item: AccountMetaEntity): AccountPointSystems => {
  const { createdAtTimestamp, createdAtBlock } = item;
  const startedAtBlock = Number(createdAtBlock);

  return {
    createdAt: {
      block: startedAtBlock,
      timestamp: Number(createdAtTimestamp) * 1000,
    },
    points: [
      {
        version: 1,
        startedAtBlock,
        ...parseAccountPoints(item),
      },
    ],
  };
};

const parseAccountPointSystem = (item: AccountPointSystemEntity): AccountPointsVersioned => {
  const { version, startedAtBlock } = item;

  return {
    version,
    startedAtBlock,
    ...parseAccountPoints(item),
  };
};

export async function fetchAccountMeta(accountAddress: string): Promise<AccountPointSystems | null> {
  const indexer = getCurrentIndexer();
  const variables = { id: accountAddress };

  try {
    if (indexer.type === IndexerType.SUBQUERY) {
      const subqueryIndexer = indexer as SubqueryIndexer;
      const response = await subqueryIndexer.services.explorer.request(SubqueryAccountMetaQuery, variables);

      if (!response) return null;

      return parseAccountMeta(response.data);
    }

    return null;
  } catch (error) {
    console.error(error);
    return null;
  }
}

export async function fetchAccountPointSystems(accountAddress: string): Promise<AccountPointsVersioned[] | null> {
  const indexer = getCurrentIndexer();
  const variables = { id: accountAddress };

  try {
    if (indexer.type === IndexerType.SUBQUERY) {
      const subqueryIndexer = indexer as SubqueryIndexer;
      const response = await subqueryIndexer.services.explorer.fetchAllEntities(
        SubqueryAccountPointSystemsQuery,
        variables,
        parseAccountPointSystem
      );

      if (!response) return null;

      return response;
    }

    return null;
  } catch (error) {
    console.error(error);
    return null;
  }
}

export async function fetchAccountPoints(accountAddress: string): Promise<AccountPointSystems | null> {
  const meta = await fetchAccountMeta(accountAddress);
  const points = await fetchAccountPointSystems(accountAddress);

  if (!meta) return null;

  return {
    createdAt: meta.createdAt,
    points: Array.isArray(points) ? points : meta.points,
  };
}

import { FPNumber } from '@sora-substrate/sdk';
import { getCurrentIndexer, WALLET_CONSTS } from '@wallet';
import { SubqueryIndexer, SubsquidIndexer } from '@wallet/lib/services/indexer';
import { gql } from '@urql/core';

import type {
  SubqueryPoolXYKEntity,
  SubquerySubscriptionPayload,
} from '@wallet/lib/services/indexer/subquery/types';
import type { SubsquidPoolXYKEntity } from '@wallet/lib/services/indexer/subsquid/types';
import type {
  ConnectionQueryResponse,
  PoolApyObject,
  SubscriptionPayload,
  UpdatesStream,
} from '@wallet/lib/services/indexer/types';

const { IndexerType } = WALLET_CONSTS;

const SubqueryApyQuery = gql<ConnectionQueryResponse<SubqueryPoolXYKEntity>>`
  query SubqueryApyQuery($after: Cursor = "", $first: Int = 100) {
    data: poolXYKs(first: $first, after: $after, filter: { strategicBonusApy: { greaterThan: "0" } }) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          id
          strategicBonusApy
        }
      }
    }
  }
`;

const SubsquidApyQuery = gql<ConnectionQueryResponse<SubsquidPoolXYKEntity>>`
  query SubsquidApyQuery($after: String = null, $first: Int = 1000) {
    data: poolXyksConnection(orderBy: id_ASC, first: $first, after: $after, where: { strategicBonusApy_gt: "0" }) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          id
          strategicBonusApy
        }
      }
    }
  }
`;

const formatStringNumber = (value: Nullable<string>) => (value ? new FPNumber(value) : FPNumber.ZERO);

const parseApy = (entity: SubsquidPoolXYKEntity | SubqueryPoolXYKEntity): PoolApyObject => {
  const acc = {};
  const id = entity.id;
  const strategicBonusApyFPNumber = formatStringNumber(entity.strategicBonusApy);
  const isStrategicBonusApyFinity = strategicBonusApyFPNumber.isFinity();
  if (isStrategicBonusApyFinity) {
    acc[id] = strategicBonusApyFPNumber.toCodecString();
  }
  return acc;
};

/**
 * Get strategic bonus APY for each pool
 */
export async function getPoolsApyObject(): Promise<Nullable<PoolApyObject>> {
  const indexer = getCurrentIndexer();

  let result: Nullable<PoolApyObject[]>;

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const subqueryIndexer = indexer as SubqueryIndexer;
      result = await subqueryIndexer.services.explorer.fetchAllEntities(SubqueryApyQuery, {}, parseApy);
      break;
    }
    case IndexerType.SUBSQUID: {
      const subsquidIndexer = indexer as SubsquidIndexer;
      result = await subsquidIndexer.services.explorer.fetchAllEntitiesConnection(SubsquidApyQuery, {}, parseApy);
      break;
    }
  }

  if (!result) return null;

  return result.reduce((acc, item) => ({ ...acc, ...item }), {});
}

const SubqueryApyStreamSubscription = gql<SubquerySubscriptionPayload<UpdatesStream>>`
  subscription SubqueryApyStreamSubscription {
    payload: updatesStreams(id: "apy", mutation: [UPDATE, INSERT]) {
      id
      mutation_type
      _entity
    }
  }
`;

const SubsquidApyStreamSubscription = gql<SubscriptionPayload<UpdatesStream>>`
  subscription SubsquidApyStreamSubscription {
    payload: updatesStreamById(id: "apy") {
      id
      block
      data
    }
  }
`;

const parseApyStreamUpdate = (entity: UpdatesStream): PoolApyObject => {
  const data = entity?.data ? JSON.parse(entity.data) : {};

  return Object.entries(data).reduce((acc, [id, apy]) => {
    const strategicBonusApyFPNumber = formatStringNumber(apy as string);
    const isStrategicBonusApyFinity = strategicBonusApyFPNumber.isFinity();
    if (isStrategicBonusApyFinity) {
      acc[id] = strategicBonusApyFPNumber.toCodecString();
    }
    return acc;
  }, {});
};

export function createPoolsApySubscription(
  handler: (entity: PoolApyObject) => void,
  errorHandler: (error: any) => void
): Nullable<VoidFunction> {
  const indexer = getCurrentIndexer();

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const subqueryIndexer = indexer as SubqueryIndexer;

      return subqueryIndexer.services.explorer.createEntitySubscription(
        SubqueryApyStreamSubscription,
        {},
        parseApyStreamUpdate,
        handler,
        errorHandler
      );
    }
    case IndexerType.SUBSQUID: {
      const subsquidIndexer = indexer as SubsquidIndexer;

      return subsquidIndexer.services.explorer.createEntitySubscription(
        SubsquidApyStreamSubscription,
        {},
        parseApyStreamUpdate,
        handler,
        errorHandler
      );
    }
  }

  return null;
}

import { FPNumber } from '@sora-substrate/sdk';
import { XOR } from '@sora-substrate/sdk/build/assets/consts';
import { getCurrentIndexer, WALLET_CONSTS } from '@wallet';
import { SubqueryIndexer, SubsquidIndexer } from '@wallet/lib/services/indexer';
import { gql } from '@urql/core';

import type {
  ConnectionQueryResponse,
  ReferrerRewardEntity,
} from '@wallet/lib/services/indexer/types';

export type ReferrerRewards = {
  rewards: FPNumber;
  invitedUserRewards: {
    [key: string]: FPNumber;
  };
};

const { IndexerType } = WALLET_CONSTS;

const SubqueryReferrerRewardsQuery = gql<ConnectionQueryResponse<ReferrerRewardEntity>>`
  query SubqueryReferrerRewardsQuery($first: Int = 100, $filter: ReferrerRewardFilter, $after: Cursor = "") {
    data: referrerRewards(first: $first, filter: $filter, after: $after) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          referral
          amount
        }
      }
    }
  }
`;

const SubsquidReferrerRewardsQuery = gql<ConnectionQueryResponse<ReferrerRewardEntity>>`
  query SubsquidReferrerRewardsQuery($first: Int = 1000, $filter: ReferrerRewardWhereInput, $after: String = null) {
    data: referrerRewardsConnection(orderBy: id_ASC, first: $first, where: $filter, after: $after) {
      pageInfo {
        hasNextPage
        endCursor
      }
      edges {
        node {
          referral
          amount
        }
      }
    }
  }
`;

/**
 * Get Referral Rewards summarized by referral
 */
export async function getReferralRewards(referrer?: string): Promise<Nullable<ReferrerRewards>> {
  const indexer = getCurrentIndexer();

  let result!: Nullable<ReferrerRewardEntity[]>;

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const filter = referrer ? { referrer: { equalTo: referrer } } : undefined;
      const variables = { filter };
      const subqueryIndexer = indexer as SubqueryIndexer;
      result = await subqueryIndexer.services.explorer.fetchAllEntities(SubqueryReferrerRewardsQuery, variables);
      break;
    }
    case IndexerType.SUBSQUID: {
      const filter = referrer ? { referrer_eq: referrer } : undefined;
      const variables = { filter };
      const subsquidIndexer = indexer as SubsquidIndexer;
      result = await subsquidIndexer.services.explorer.fetchAllEntitiesConnection(
        SubsquidReferrerRewardsQuery,
        variables
      );
      break;
    }
  }

  if (!result) return null;

  return result.reduce<ReferrerRewards>(
    (acc, node) => {
      const { referral, amount } = node;
      const value = FPNumber.fromCodecValue(amount, XOR.decimals);

      acc.rewards = acc.rewards.add(value);
      acc.invitedUserRewards[referral] = (acc.invitedUserRewards[referral] ?? FPNumber.ZERO).add(value);

      return acc;
    },
    {
      rewards: FPNumber.ZERO,
      invitedUserRewards: {},
    }
  );
}

import { FPNumber } from '@sora-substrate/sdk';
import { getCurrentIndexer, WALLET_CONSTS } from '@wallet';
import { SubqueryIndexer, SubsquidIndexer } from '@wallet/lib/services/indexer';
import { gql } from '@urql/core';

import type { VaultEvent } from '@/modules/vault/types';
import type { FetchVariables } from '@/types/indexers';

import type { SubsquidQueryResponse } from '@wallet/lib/services/indexer/subsquid/types';
import type {
  ConnectionQueryResponse,
  VaultEventBaseEntity,
} from '@wallet/lib/services/indexer/types';

const { IndexerType } = WALLET_CONSTS;

const SubqueryVaultDetailsQuery = gql<ConnectionQueryResponse<VaultEventBaseEntity>>`
  query VaultDetailsQuery($first: Int = null, $offset: Int = null, $filter: VaultEventFilter) {
    data: vaultEvents(first: $first, offset: $offset, filter: $filter, orderBy: [TIMESTAMP_DESC, ID_DESC]) {
      pageInfo {
        hasNextPage
        endCursor
      }
      totalCount
      edges {
        node {
          id
          amount
          type
          timestamp
        }
      }
    }
  }
`;

const SubsquidVaultDetailsQuery = gql<SubsquidQueryResponse<VaultEventBaseEntity>>`
  query VaultDetailsQuery($first: Int = null, $offset: Int = null, $filter: VaultEventWhereInput) {
    info: vaultEventsConnection(first: 0, where: $filter, orderBy: [timestamp_DESC, id_DESC]) {
      totalCount
    }
    nodes: vaultEvents(limit: $first, offset: $offset, where: $filter, orderBy: [timestamp_DESC, id_DESC]) {
      id
      amount
      type
      timestamp
    }
  }
`;

const subqueryVaultEventsFilter = (vaultId: string | number, fromTimestamp?: number) => {
  const filter: any = { vaultId: { equalTo: String(vaultId) } };

  if (fromTimestamp) filter.timestamp = { greaterThan: fromTimestamp };

  return filter;
};

const parseVaultEvents = (event: VaultEventBaseEntity): VaultEvent => {
  return {
    amount: event.amount ? new FPNumber(event.amount) : null,
    timestamp: event.timestamp * 1000,
    type: event.type,
  };
};

export async function fetchVaultEvents(variables: FetchVariables): Promise<{
  totalCount: number;
  items: VaultEvent[];
}> {
  const indexer = getCurrentIndexer();
  const { id, first, offset, fromTimestamp } = variables;

  let totalCount = 0;
  let items: VaultEvent[] = [];

  if (!id) return { totalCount, items };

  switch (indexer.type) {
    case IndexerType.SUBQUERY: {
      const filter = subqueryVaultEventsFilter(id, fromTimestamp);
      const variables = { first, offset, filter };
      const subqueryIndexer = indexer as SubqueryIndexer;
      const response = await subqueryIndexer.services.explorer.fetchEntities(SubqueryVaultDetailsQuery, variables);
      if (response) {
        totalCount = response.totalCount;
        items = response.edges.map((edge) => parseVaultEvents(edge.node));
      }
      break;
    }
    case IndexerType.SUBSQUID: {
      const filter = subqueryVaultEventsFilter(id, fromTimestamp);
      const variables = { first, offset, filter };
      const subsquidIndexer = indexer as SubsquidIndexer;
      const response = await subsquidIndexer.services.explorer.fetchEntities(SubsquidVaultDetailsQuery, variables);
      if (response) {
        totalCount = response.totalCount;
        items = response.nodes.map((edge) => parseVaultEvents(edge));
      }
      break;
    }
  }

  return { totalCount, items };
}

import dayjs from 'dayjs';
import first from 'lodash/fp/first';
import { createI18n } from 'vue-i18n'; // eslint-disable-line import/named

import { Language, TranslationConsts } from '@/consts';
import { settingsStorage } from '@/utils/storage';

import enCard from './card/en.json';
import en from './en.json';

const i18n = createI18n({
  legacy: false,
  globalInjection: true,
  locale: Language.EN,
  fallbackLocale: Language.EN,
  messages: {
    [Language.EN]: { ...en, ...enCard },
  },
  warnHtmlMessage: false,
});

const i18nGlobal = i18n.global;
const loadedLanguages: Array<string> = [Language.EN];
applyDocumentDirection(Language.EN);

// Set document direction for RTL languages
const rtlLocales = [Language.AR, Language.HE, Language.UR, Language.DV];
function applyDocumentDirection(locale: string): void {
  try {
    if (typeof document !== 'undefined') {
      const dir = rtlLocales.includes(locale as Language) ? 'rtl' : 'ltr';
      document.documentElement.setAttribute('dir', dir);
    }
  } catch (e) {
    // noop: environment may not have document (tests)
  }
}

const hasLocale = (locale: string) => Object.values(Language).includes(locale as any);

export const getSupportedLocale = (locale: Language): string => {
  if (hasLocale(locale)) return locale;

  if (locale.includes('-')) {
    return getSupportedLocale(first(locale.split('-')) as Language);
  }

  return Language.EN;
};

export function getLocale(): string {
  const locale = settingsStorage.get('language') || ((navigator.language || (navigator as any).userLanguage) as string);

  return getSupportedLocale(locale as Language);
}

export async function setDayJsLocale(lang: Language): Promise<void> {
  const locale = getSupportedLocale(lang);
  let code: string = locale;

  if (locale !== Language.ZH_CN && locale !== Language.ZH_TW && locale.includes('-')) {
    code = first(locale.split('-')) as string;
  }

  if (code === 'zh') {
    code = Language.ZH_CN;
  }

  if (locale === Language.ZH_CN || locale === Language.ZH_TW) {
    code = locale;
  }

  const dayjsLocale = code.toLowerCase();

  try {
    const { default: preset } = dayjsLocale !== Language.EN ? await import(`dayjs/esm/locale/${dayjsLocale}.js`) : {};
    dayjs.locale(dayjsLocale, preset, false);
  } catch (error) {
    console.warn(`[dayjs]: unsupported locale "${code}"`, error);
  }
}

export async function setI18nLocale(lang: Language): Promise<void> {
  const locale = getSupportedLocale(lang) as Language;

  if (!loadedLanguages.includes(locale)) {
    // transform locale string 'eu-ES' to filename 'eu_ES' like in localise
    const filename = locale.replace('-', '_');
    const messagesModule = await import(`@/lang/${filename}.json`);
    const cardMessagesModule = await import(`@/lang/card/${filename}.json`);

    i18nGlobal.setLocaleMessage(locale, { ...messagesModule.default, ...cardMessagesModule.default });
    loadedLanguages.push(locale);
  }

  i18nGlobal.locale.value = locale;
  applyDocumentDirection(locale);

  // Apply locale-specific constant overrides (non-critical, optional)
  if (locale === Language.AKK) {
    try {
      (TranslationConsts as any).AppName = '𒊹𒂵𒆜'; // Polkaswap
      if ((TranslationConsts as any).Sora) (TranslationConsts as any).Sora = '𒀭'; // SORA
      (TranslationConsts as any).VAL = '𒋾';
    } catch (e) {
      // noop
    }
  }
}
const globalComposer = i18n.global as Record<string, unknown>;
if (typeof globalComposer.rt !== 'function') {
  globalComposer.rt = (...args: unknown[]) => (i18n.global as any).t(...(args as [unknown]));
}

