import { describe, expect, test, vi } from 'vitest'
import { BODY_SCROLL_LOCK_API_KEY, useBodyScrollLockIfPossible } from './index'
import { createApp, defineComponent, h, nextTick, ref } from 'vue'

describe('useBodyScrollLockIfPossible', () => {
  test('locks and unlocks when target changes', async () => {
    const lock = vi.fn()
    const unlock = vi.fn()
    const element = document.createElement('div')
    let toggle: ((value: HTMLElement | null) => void) | undefined

    const Harness = defineComponent({
      setup() {
        const target = ref<HTMLElement | null>(null)
        useBodyScrollLockIfPossible(target)
        toggle = (value) => {
          target.value = value
        }
        return () => h('div')
      },
    })

    const app = createApp(Harness)
    app.provide(BODY_SCROLL_LOCK_API_KEY, { lock, unlock })
    app.mount(document.createElement('div'))

    toggle?.(element)
    await nextTick()
    expect(lock).toHaveBeenCalledWith(element)

    toggle?.(null)
    await nextTick()
    expect(unlock).toHaveBeenCalledWith(element)

    app.unmount()
    expect(unlock).toHaveBeenCalledTimes(1)
  })

  test('does nothing when API is absent', () => {
    const Harness = defineComponent({
      setup() {
        useBodyScrollLockIfPossible(ref(null))
        return () => h('div')
      },
    })

    const app = createApp(Harness)
    expect(() => app.mount(document.createElement('div'))).not.toThrow()
    app.unmount()
  })
})

import { computed, defineComponent, inject, onScopeDispose, provide, watch, type InjectionKey, type PropType } from 'vue'
import { unrefElement, type MaybeElementRef } from '@vueuse/core'

export interface BodyScrollLockApi {
  lock: (elem: Element) => void
  unlock: (elem: Element) => void
}

export const BODY_SCROLL_LOCK_API_KEY: InjectionKey<BodyScrollLockApi> = Symbol('SBodyScrollLockApi')

export const SBodyScrollLockProvider = /* @__PURE__ */ defineComponent({
  name: 'SBodyScrollLockProvider',
  props: {
    api: {
      type: Object as PropType<BodyScrollLockApi>,
      required: true,
    },
  },
  setup(props, { slots }) {
    provide(BODY_SCROLL_LOCK_API_KEY, props.api)
    return () => slots.default?.()
  },
})

/**
 * tip: if you want to make it conditional, pass maybe-null-ref as target
 */
export function useBodyScrollLockIfPossible(target: MaybeElementRef) {
  const api = inject(BODY_SCROLL_LOCK_API_KEY, undefined)
  if (!api) return

  const targetNormalized = computed(() => unrefElement(target))

  watch(
    targetNormalized,
    (elem, prevElem) => {
      if (prevElem) {
        api.unlock(prevElem)
      }

      if (elem) {
        api.lock(elem)
      }
    },
    { immediate: true },
  )

  onScopeDispose(() => {
    const elem = targetNormalized.value
    elem && api.unlock(elem)
  })
}

