import type { Ref } from 'vue'

interface TableHeightsComposableParams {
  propHeight: Ref<number | string>
  propMaxHeight: Ref<number | string>
  headerHeight: Ref<number>
  tableHeight: Ref<number>
}

export function useTableHeights({
  propHeight,
  propMaxHeight,
  headerHeight,
  tableHeight,
}: TableHeightsComposableParams) {
  function parseHeight(height: string | number) {
    if (typeof height === 'number') {
      return height
    }

    if (/^\d+(?:px)?$/.test(height)) {
      return parseInt(height, 10)
    }

    return height
  }

  const tableHeightStyles = computed(() => {
    const parsedHeight = parseHeight(propHeight.value)
    const parsedMaxHeight = parseHeight(propMaxHeight.value)

    return {
      height: typeof parsedHeight === 'number' ? parsedHeight + 'px' : parsedHeight,
      'max-height': typeof parsedMaxHeight === 'number' ? parsedMaxHeight + 'px' : parsedMaxHeight,
    }
  })

  const bodyHeightStyles = ref({})

  watch(
    [headerHeight, tableHeight],
    () => {
      if (propHeight.value) {
        const bodyHeight = tableHeight.value - headerHeight.value

        bodyHeightStyles.value = {
          height: bodyHeight ? bodyHeight + 'px' : '',
        }

        return
      }

      if (propMaxHeight.value) {
        const maxHeight = parseHeight(propMaxHeight.value)

        if (typeof maxHeight === 'number') {
          const computedMaxHeight = Math.max(maxHeight - headerHeight.value, 0)

          bodyHeightStyles.value = {
            'max-height': computedMaxHeight + 'px',
          }

          return
        }
      }

      bodyHeightStyles.value = {}
    },
    { immediate: true },
  )

  return {
    tableHeightStyles,
    bodyHeightStyles,
  }
}

import type { TableActionColumnApi, TableColumnApi } from './api'
import type { TableRow } from '@soramitsu-ui/ui/components'
import { get } from 'lodash-es'

export function isDefaultColumn(column: TableColumnApi | TableActionColumnApi): column is TableColumnApi {
  return column.type === 'default'
}

export function isSelectionColumn(
  column: TableColumnApi | TableActionColumnApi,
): column is TableActionColumnApi & { type: 'selection' } {
  return column.type === 'selection'
}

export function isExpandColumn(
  column: TableColumnApi | TableActionColumnApi,
): column is TableActionColumnApi & { type: 'expand' } {
  return column.type === 'expand'
}

export function isDetailsColumn(
  column: TableColumnApi | TableActionColumnApi,
): column is TableActionColumnApi & { type: 'details' } {
  return column.type === 'details'
}

// Without type predicate checked like this object becomes object without keys
export function isRecord(obj: unknown): obj is Record<string, unknown> {
  return obj !== null && typeof obj === 'object'
}

export function getDefaultCellValue(row: TableRow, column: TableColumnApi, index: number) {
  return column.formatter ? column.formatter(row, column, get(row, column.prop), index) : get(row, column.prop)
}

export function getCellTooltipContent(row: TableRow, column: TableColumnApi | TableActionColumnApi) {
  if (!column.showOverflowTooltip || !isDefaultColumn(column)) {
    return ''
  }

  return String(get(row, column.prop))
}

import { forceInject } from '@soramitsu-ui/ui/util'
import type { InjectionKey } from 'vue'

export interface TabsPanelApi {
  active: string
  selectTab: (tab: string) => void
  background: TabsPanelBackgroundType
