import type { Ref, EffectScope } from 'vue'
import { effectScope, watch, onScopeDispose } from 'vue'

export function useConditionalScope(enabled: Ref<boolean>, scopeSetupFn: () => void) {
  let scope: EffectScope | null = null

  function setupScope() {
    scope = effectScope()
    scope.run(scopeSetupFn)
  }

  function stopScope() {
    scope?.stop()
  }

  watch(
    enabled,
    (flag) => {
      if (flag) {
        setupScope()
      } else {
        stopScope()
      }
    },
    { immediate: true },
  )

  onScopeDispose(stopScope)
}

import type { FocusTrap, Options } from 'focus-trap'
import { createFocusTrap } from 'focus-trap'
import type { MaybeElementRef } from '@vueuse/core'
import { unrefElement } from '@vueuse/core'
import type { Ref } from 'vue'
import { shallowRef, markRaw, watch, computed, onScopeDispose } from 'vue'

export interface UseFocusTrapParams {
  elem: MaybeElementRef

  /**
   * One-time, no reactivity
   */
  options?: Options
}

export interface UseFocusTrapReturn {
  trap: Ref<null | FocusTrap>
}

export function useFocusTrap(params: UseFocusTrapParams): UseFocusTrapReturn {
  const trap = shallowRef<null | FocusTrap>(null)

  const elem = computed(() => unrefElement(params.elem))

  watch(
    elem,
    (el) => {
      const tr = trap.value

      if (el) {
        if (tr) {
          tr.updateContainerElements(el)
        } else {
          const newTrap = markRaw(createFocusTrap(el, params.options))
          trap.value = newTrap
        }
      } else if (tr) {
        tr.deactivate()
        trap.value = null
      }
    },
    { immediate: true },
  )

  onScopeDispose(() => {
    trap.value?.deactivate()
  })

  return { trap }
}

import { nextTick, ref, watch, type Ref } from 'vue'

interface PassiveModelOptions {
  deep?: boolean
}

export function usePassiveModel<T>(model: Ref<T>, options: PassiveModelOptions = {}): Ref<T> {
  const { deep = false } = options
  const proxy = ref(model.value) as Ref<T>
  let isUpdating = false

  watch(
    model,
    (value) => {
      if (isUpdating) return
      isUpdating = true
      proxy.value = value
      nextTick(() => {
        isUpdating = false
      })
    },
    { deep },
  )

  watch(
    proxy,
    (value) => {
      if (isUpdating) return
      if (deep || !Object.is(value, model.value)) {
        model.value = value
      }
    },
    { deep },
  )

  return proxy
}

import type { VirtualElement, Instance, Options } from '@popperjs/core'
import { createPopper } from '@popperjs/core'
import type { MaybeRef } from '@vueuse/core'
import type { Ref } from 'vue'
import { computed, watch, unref, shallowRef, onScopeDispose, isReactive } from 'vue'

type ElementReference = Element | VirtualElement
type ElementPopper = HTMLElement

export interface UsePopperParams {
  referenceElem: MaybeRef<ElementReference | null>
  popperElem: MaybeRef<ElementPopper | null>
  options?: MaybeRef<Partial<Options>>
  callbackInit?: (reference: ElementReference, popper: ElementPopper) => Instance
  callbackDestroy?: (instance: Instance) => void
}

export interface UsePopperReturn {
  instance: Ref<Instance | null>
}

export function usePopper(params: UsePopperParams): UsePopperReturn {
  const elemReference = computed(() => unref(params.referenceElem))
  const elemPopper = computed(() => unref(params.popperElem))
  const opts = params.options || {}

  const instance = shallowRef<Instance | null>(null)

  function init(reference: ElementReference, popper: ElementPopper) {
    instance.value = markRaw(params.callbackInit?.(reference, popper) ?? createPopper(reference, popper, unref(opts)))
  }

  function destroy() {
    instance.value && (params.callbackDestroy ? params.callbackDestroy(instance.value) : instance.value.destroy())
  }

  watch(
    [elemReference, elemPopper],
    ([a, b]) => {
      destroy()
      a && b && init(a, b)
    },
    { immediate: true },
  )
  onScopeDispose(destroy)

  if (isReactive(opts)) {
    watch(
      opts,
      (updated) => {
        if (instance.value) {
          instance.value.setOptions(unref(updated))
        }
      },
      { deep: true },
    )
  }

  return { instance }
}

import { computed, type ComputedRef } from 'vue'

type PropName<T> = Extract<keyof T, string | number>

const formatToLog = (value: unknown) => (typeof value === 'string' ? `'${value}'` : JSON.stringify(value))

const BUTTON_TYPE_VALUES_LEGACY = ['primary', 'secondary', 'outline', 'action'] as const
const BUTTON_TYPE_ALIASES: Record<string, string> = {
  tertiary: 'secondary',
  link: 'secondary',
  text: 'secondary',
}

const BUTTON_SIZE_VALUES_LEGACY = ['xs', 'sm', 'md', 'lg'] as const
const BUTTON_SIZE_ALIASES: Record<string, string> = {
  mini: 'xs',
  tiny: 'xs',
  small: 'sm',
  medium: 'md',
  big: 'lg',
  large: 'lg',
}

const asValueSet = <T>(values: readonly T[]): Set<T> => new Set(values)

function normalizeLegacyValue<T extends Record<PropertyKey, unknown>>(
  _name: PropName<T>,
  value: unknown,
  validValues: readonly unknown[],
): unknown {
  if (typeof value !== 'string') {
    return value
  }

  const valueSet = asValueSet(validValues)

  const isButtonType = BUTTON_TYPE_VALUES_LEGACY.every((item) => valueSet.has(item))
  if (isButtonType) {
    const alias = BUTTON_TYPE_ALIASES[value]
    if (alias && valueSet.has(alias)) {
      return alias
    }
    return value
  }

  const isButtonSize = BUTTON_SIZE_VALUES_LEGACY.every((item) => valueSet.has(item))
  if (isButtonSize) {
    const alias = BUTTON_SIZE_ALIASES[value]
    if (alias && valueSet.has(alias)) {
      return alias
    }
    return value
  }

  return value
}

export function usePropTypeFilter<T extends Record<PropertyKey, unknown>>(props: T) {
  return function <K extends PropName<T>>(
    name: K,
    validValues: readonly T[K][],
    defaultValue: T[K],
  ): ComputedRef<T[K]> {
    return computed(() => {
      const candidate = normalizeLegacyValue<T>(name, props[name], validValues) as T[K]

      if (validValues.includes(candidate)) {
        return candidate
      }

      const formattedList = validValues.map(formatToLog).join(' | ')
      const formattedValue = formatToLog(props[name])

      console.warn(
        `[soramitsu-ui warn]: Invalid prop: type check failed for prop "${String(
          name,
        )}". Expected: ${formattedList}, got ${formattedValue}`,
      )

      return defaultValue
    })
  }
}

