import { flushPromises } from '@vue/test-utils'
import { defineStore } from 'pinia'
import { describe, expect, it } from 'vitest'
import { defineComponent, h, nextTick, type PropType } from 'vue'
import { useRoute } from 'vue-router'
import { createTestPinia, createTestRouter, mountWithPinia, mountWithProviders, mountWithRouter } from '@soramitsu-ui/ui/test-utils'

type StoreFactory = () => { value: string }

const TestHarness = defineComponent({
  name: 'TestHarness',
  props: {
    showRoute: {
      type: Boolean,
      default: false,
    },
    useStore: {
      type: Function as PropType<StoreFactory>,
      default: undefined,
    },
  },
  setup(props) {
    const route = props.showRoute ? useRoute() : undefined
    const store = props.useStore ? props.useStore() : undefined

    return () => {
      if (props.showRoute && route && store) {
        return h('span', `${route.path} - ${store.value}`)
      }

      if (props.showRoute && route) {
        return h('span', route.path)
      }

      return h('span', store?.value ?? '')
    }
  },
})

describe('test-utils/vue', () => {
  it('mountWithRouter wires vue-router and exposes the instance', async () => {
    const wrapper = mountWithRouter(TestHarness, {
      props: { showRoute: true },
      router: {
        routes: [{ path: '/', name: 'home', component: { template: '<div />' } }],
        initialRoute: '/',
      },
    })

    await wrapper.router?.isReady()
    await flushPromises()
    await nextTick()

    expect(wrapper.router).toBeDefined()
    expect(wrapper.text()).toBe('/')
  })

  it('mountWithPinia installs a Pinia instance and shares stores', () => {
    const useTestStore = defineStore('test-store', {
      state: () => ({ value: 'works' }),
    })

    const wrapper = mountWithPinia(TestHarness, {
      props: {
        useStore: useTestStore,
      },
    })

    expect(wrapper.pinia).toBeDefined()
    expect(wrapper.text()).toBe('works')
  })

  it('mountWithProviders accepts existing router and pinia instances', async () => {
    const router = createTestRouter({
      routes: [
        { path: '/', name: 'home', component: { template: '<div />' } },
        { path: '/other', name: 'other', component: { template: '<div />' } },
      ],
    })
    const pinia = createTestPinia()

    const useSecondStore = defineStore('second-store', {
      state: () => ({ value: 'from pinia' }),
    })

    const wrapper = mountWithProviders(TestHarness, {
      props: {
        showRoute: true,
        useStore: useSecondStore,
      },
      router,
      pinia,
    })

    await wrapper.router?.push('/other')
    await wrapper.router?.isReady()
    await flushPromises()
    await nextTick()

    expect(wrapper.router).toBe(router)
    expect(wrapper.pinia).toBe(pinia)
    expect(wrapper.router?.currentRoute.value.path).toBe('/other')
    expect(wrapper.text()).toContain('from pinia')
  })
})

import { mount, type MountingOptions } from '@vue/test-utils'
import type { Component } from 'vue'
import {
  createMemoryHistory,
  createRouter,
  type RouteRecordRaw,
  type Router,
  type RouterHistory,
  type RouterOptions,
} from 'vue-router'
import { createPinia, setActivePinia, type Pinia, type PiniaPlugin } from 'pinia'

type BaseMountOptions = MountingOptions<any>

type MountResult = ReturnType<typeof mount> & {
  router?: Router
  pinia?: Pinia
}

export interface RouterPresetOptions extends Omit<RouterOptions, 'history' | 'routes'> {
  history?: RouterHistory
  initialRoute?: string
  routes?: RouteRecordRaw[]
}

export interface PiniaPresetOptions {
  autoActivate?: boolean
  create?: () => Pinia
  instance?: Pinia
  plugins?: PiniaPlugin[]
}

export type MountHelperOptions = BaseMountOptions & {
  pinia?: boolean | Pinia | PiniaPresetOptions
  router?: boolean | Router | RouterPresetOptions
}

function resolveRouter(router?: MountHelperOptions['router']): Router | undefined {
  if (!router) {
    return undefined
  }

  if (router === true) {
    return createRouter({
      history: createMemoryHistory(),
      routes: [],
    })
  }

  if (typeof (router as Router).install === 'function') {
    return router as Router
  }

  const { history, initialRoute, routes = [], ...rest } = router as RouterPresetOptions
  const resolvedHistory = history ?? createMemoryHistory()

  if (initialRoute) {
    resolvedHistory.replace?.(initialRoute)
  }

  const instance = createRouter({
    history: resolvedHistory,
    routes,
    ...rest,
  })

  if (initialRoute) {
    instance.push(initialRoute).catch(() => undefined)
  }

  return instance
}

function resolvePinia(pinia?: MountHelperOptions['pinia']): Pinia | undefined {
  if (!pinia) {
    return undefined
  }

  if (pinia === true) {
    const instance = createPinia()
    setActivePinia(instance)
    return instance
  }

  if (typeof (pinia as Pinia).install === 'function') {
    const instance = pinia as Pinia
    setActivePinia(instance)
    return instance
  }

  const { autoActivate = true, create = createPinia, instance, plugins = [] } = pinia as PiniaPresetOptions
  const resolvedInstance = instance ?? create()

  plugins.forEach((plugin) => {
    resolvedInstance.use(plugin)
  })

  if (autoActivate) {
    setActivePinia(resolvedInstance)
  }

  return resolvedInstance
}

export function createTestRouter(options: Router | RouterPresetOptions | true = true): Router {
  const router = resolveRouter(options)

  if (!router) {
    throw new Error('createTestRouter requires router configuration')
  }

  return router
}

export function createTestPinia(options: Pinia | PiniaPresetOptions | true = true): Pinia {
  const pinia = resolvePinia(options)

  if (!pinia) {
    throw new Error('createTestPinia requires pinia configuration')
  }

  return pinia
}

export function mountWithProviders(component: Component, options: MountHelperOptions = {}): MountResult {
  const { router, pinia, global, ...rest } = options
  const resolvedRouter = resolveRouter(router)
  const resolvedPinia = resolvePinia(pinia)

  const baseGlobal: NonNullable<BaseMountOptions['global']> = {
    ...(global ?? {}),
    stubs: {
      transition: false,
      'transition-group': false,
      ...(global?.stubs ?? {}),
    },
  }

  const plugins = [...(baseGlobal.plugins ?? [])]

  if (resolvedRouter) {
    plugins.push(resolvedRouter)
  }

  if (resolvedPinia) {
    plugins.push(resolvedPinia)
  }

  if (plugins.length > 0) {
    baseGlobal.plugins = plugins
  }

  const wrapper = mount(component as any, {
    ...rest,
    global: baseGlobal,
  }) as MountResult

  if (resolvedRouter) {
    Object.assign(wrapper, { router: resolvedRouter })
  }

  if (resolvedPinia) {
    Object.assign(wrapper, { pinia: resolvedPinia })
  }

  return wrapper
}

export function mountWithRouter(component: Component, options: MountHelperOptions = {}): MountResult {
  return mountWithProviders(component, {
    ...options,
    router: options.router ?? true,
  })
}

export function mountWithPinia(component: Component, options: MountHelperOptions = {}): MountResult {
  return mountWithProviders(component, {
    ...options,
    pinia: options.pinia ?? true,
  })
}

import { describe, expect, test } from '@jest/globals'
import { themeTokenIds, themeTokens } from '../tokens'

describe('theme tokens', () => {
  test('includes known flattened ids', () => {
    expect(themeTokenIds).toEqual(expect.arrayContaining(['sys.color.primary', 'sys.shadow.dropdown']))
  })

  test('every leaf value is represented in the flattened list', () => {
    const collect = (obj: Record<string, any>, prefix = ''): string[] =>
      Object.entries(obj).flatMap(([key, value]) => {
        const id = prefix ? `${prefix}.${key}` : key
        if (value && typeof value === 'object' && !Array.isArray(value)) {
          return collect(value, id)
        }
        return [id]
      })

    const flattened = collect(themeTokens as unknown as Record<string, any>)
    expect(new Set(themeTokenIds)).toEqual(new Set(flattened))
  })
})

import { describe, expect, test } from '@jest/globals'
import { spawnSync } from 'node:child_process'
import path from 'node:path'

function compile(fragment: string) {
  const script = `const { readFileSync } = require('node:fs')
const path = require('node:path')
const sass = require('sass')

const payload = JSON.parse(readFileSync(0, 'utf8'))
const loadPath = path.resolve(payload.cwd, '../sass')

try {
  const result = sass.compileString("@use 'util' as util;\\n" + payload.fragment, {
    style: 'expanded',
    loadPaths: [loadPath],
  })

  process.stdout.write(JSON.stringify({ css: result.css }))
} catch (error) {
  process.stderr.write(error instanceof Error ? error.stack || error.message : String(error))
  process.exit(1)
}
`

  const payload = JSON.stringify({ fragment, cwd: __dirname })
  const child = spawnSync(process.execPath, ['-e', script], { encoding: 'utf8', input: payload })

  if (child.status !== 0) {
    throw new Error(child.stderr || `Sass compilation failed with exit code ${child.status}`)
  }

  return child.stdout ? JSON.parse(child.stdout) : { css: '' }
}

