  InjectedExtension,
  InjectedMetadata,
  InjectedProvider,
  InjectedWindow,
} from '@polkadot/extension-inject/types';
import type { Signer } from '@polkadot/api/types';

import { SubscriptionFn, Wallet, WalletAccount, WalletInfo, WalletLogoProps } from './types';

/**
 * Base implementation for wallets that integrate through the polkadot.js
 * extension APIs. Concrete wallets only need to supply static metadata, while
 * this class encapsulates extension detection and account management.
 */
export class BaseDotSamaWallet implements Wallet {
  dAppName: string;

  extensionName: string;
  title: string;
  chromeUrl: string;
  mozillaUrl: string;
  installUrl: string;
  logo: WalletLogoProps;

  _extension: InjectedExtension | undefined;
  _signer: Signer | undefined;
  _metadata: InjectedMetadata | undefined;
  _provider: InjectedProvider | undefined;

  constructor({ extensionName, chromeUrl, mozillaUrl, logo, title }: WalletInfo, dAppName = 'dApp Connect') {
    this.extensionName = extensionName;
    this.title = title;
    this.chromeUrl = chromeUrl;
    this.mozillaUrl = mozillaUrl;
    this.installUrl = /firefox|fxios/i.test(navigator.userAgent) ? mozillaUrl : chromeUrl; // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
    this.logo = logo;

    this.dAppName = dAppName;
  }

  // API docs: https://polkadot.js.org/docs/extension/
  get extension() {
    return this._extension;
  }

  // API docs: https://polkadot.js.org/docs/extension/
  get signer() {
    return this._signer;
  }

  get metadata() {
    return this._metadata;
  }

  get provider() {
    return this._provider;
  }

  /**
   * Indicates whether the wallet extension is available in the user's
   * browser. The check mirrors the logic used by the polkadot.js extension.
   */
  get installed() {
    const injectedWindow = window as Window & InjectedWindow;
    const injectedExtension = injectedWindow?.injectedWeb3?.[this.extensionName];

    return !!injectedExtension;
  }

  /**
   * Returns the raw injected extension object without applying any local
   * normalization. Consumers usually call {@link enable} instead.
   */
  get rawExtension() {
    const injectedWindow = window as Window & InjectedWindow;

    return injectedWindow?.injectedWeb3?.[this.extensionName];
  }

  /**
   * Requests access to the extension and caches the normalized response so
   * subsequent calls do not re-trigger the permission prompt.
   */
  enable = async () => {
    if (!this.installed) {
      return;
    }

    const injectedExtension = this.rawExtension;

    if (!injectedExtension?.enable) {
      return;
    }

    const rawExtension = await injectedExtension.enable(this.dAppName);

    if (!rawExtension) {
      return;
    }

    const extension: InjectedExtension = {
      ...rawExtension,
      // Manually add `InjectedExtensionInfo` so as to have a consistent response.
      name: this.extensionName,
      version: injectedExtension.version ?? 'unknown',
    };

    this._extension = extension;
    this._signer = extension?.signer as unknown as Signer;
    this._metadata = extension?.metadata;
    this._provider = extension?.provider;
  };

  /**
   * Augments accounts returned by the extension with wallet specific helpers
   * so downstream code can rely on a consistent shape.
   */
  private generateWalletAccount = (account: InjectedAccount): WalletAccount => {
    return {
      ...account,
      source: this._extension?.name as string,
      // Added extra fields here for convenience
      wallet: this,
      signer: this._extension?.signer as unknown as Signer,
    } as WalletAccount;
  };

  /**
   * Subscribes to account updates emitted by the extension. The callback is
   * invoked with the wallet enhanced accounts whenever changes occur.
   */
  subscribeAccounts = async (callback: SubscriptionFn) => {
    if (!this._extension) {
      await this?.enable();
    }

    if (!this._extension) {
      // eslint-disable-next-line @typescript-eslint/no-floating-promises
      callback(undefined);

      return null;
    }

    return this._extension.accounts.subscribe((accounts: InjectedAccount[]) => {
      const accountsWithWallet = accounts.map(this.generateWalletAccount);

      // eslint-disable-next-line @typescript-eslint/no-floating-promises
      callback(accountsWithWallet);
    });
  };

  /**
   * Returns the current list of accounts by querying the extension on demand.
   * The accounts are wrapped with wallet helpers for downstream consumers.
   */
  getAccounts = async () => {
    if (!this._extension) {
      await this?.enable();
    }

    if (!this._extension) {
      return null;
    }

    const accounts = await this._extension.accounts.get();

    return accounts.map(this.generateWalletAccount);
  };
}

import { createAppKit } from '@reown/appkit/vue';

import { TranslationConsts } from '../../consts';

import type { AppKit } from '@reown/appkit';
import type { AppKitOptions } from '@reown/appkit';
import type { AppKitNetwork, ChainNamespace } from '@reown/appkit-common';
import type { ChainId } from './provider/base';

type WalletConnectModalState = { open: boolean };

export type WalletConnectModal = {
  openModal: (options?: { uri?: string }) => Promise<void>;
  closeModal: () => Promise<void>;
  subscribeModal: (callback: (state: WalletConnectModalState) => void) => () => void;
};

type EnsureModalConfig = {
  projectId: string;
  namespace: ChainNamespace;
  chains: ChainId[];
  optionalChains?: ChainId[];
};

const APPKIT_THEME: NonNullable<AppKitOptions['themeVariables']> = {
  '--w3m-font-family': 'var(--s-font-family, "Inter", sans-serif)',
  '--w3m-accent': 'var(--s-color-theme-accent, #ff931e)',
  '--w3m-color-mix': 'var(--s-color-theme-accent, #ff931e)',
  '--w3m-color-mix-strength': 25,
  '--w3m-qr-color': 'var(--s-color-theme-accent, #ff931e)',
  '--w3m-z-index': 9999,
};

const DEFAULT_ICON_PATH = '/favicon.ico';
const DEFAULT_CHAIN_ID = 'sora-mainnet';

let appKitPromise: Promise<AppKit> | null = null;
let cachedProjectId: string | null = null;
let cachedNamespace: ChainNamespace | null = null;
let cachedNetworks: AppKitNetwork[] = [];

const toNetworkId = (value: ChainId): string => {
  if (typeof value === 'number') {
    return value.toString(10);
  }

  return String(value);
};

const buildRpcUrls = (namespace: ChainNamespace, id: ChainId, projectId: string): string[] => {
  const plainId = toNetworkId(id);

  return [`https://rpc.walletconnect.com/v1/?chainId=${namespace}:${plainId}&projectId=${projectId}`];
};

const buildNetworkName = (namespace: ChainNamespace, id: ChainId): string => {
  if (namespace === 'polkadot') {
    const plainId = toNetworkId(id);
    return plainId.length > 8 ? `Substrate ${plainId.slice(2, 8).toUpperCase()}` : `Substrate ${plainId}`;
  }

  return `${namespace.toUpperCase()} ${toNetworkId(id)}`;
};

const buildNetworks = (config: EnsureModalConfig): AppKitNetwork[] => {
  const { namespace, chains, projectId } = config;
  const unique = new Map<string, AppKitNetwork>();
  const sourceIds = chains.length ? chains : [DEFAULT_CHAIN_ID];

  sourceIds.forEach((id) => {
    const plainId = toNetworkId(id);
    const network: AppKitNetwork = {
      id,
      name: buildNetworkName(namespace, id),
      nativeCurrency: {
        name: 'SORA',
        symbol: 'XOR',
        decimals: 18,
      },
      rpcUrls: {
        default: {
          http: buildRpcUrls(namespace, id, projectId),
        },
        public: {
          http: buildRpcUrls(namespace, id, projectId),
        },
      },
      testnet: false,
      chainNamespace: namespace,
      caipNetworkId: `${namespace}:${plainId}`,
    };

    unique.set(plainId, network);
  });

  const networks = Array.from(unique.values());

  if (networks.length === 0) {
    throw new Error('Unable to resolve AppKit networks');
  }

  return networks;
};

const getMetadata = (): NonNullable<AppKitOptions['metadata']> => {
  const origin = typeof window !== 'undefined' && window.location?.origin ? window.location.origin : 'https://polkaswap.io';

  return {
    name: TranslationConsts.Polkaswap,
    description: TranslationConsts.Polkaswap,
    url: origin,
    icons: [`${origin}${DEFAULT_ICON_PATH}`],
  };
};

const ensureAppKit = async (config: EnsureModalConfig): Promise<AppKit> => {
  const { namespace, chains, optionalChains, projectId } = config;

  if (!appKitPromise || cachedProjectId !== projectId || cachedNamespace !== namespace) {
    cachedProjectId = projectId;
    cachedNamespace = namespace;
    cachedNetworks = buildNetworks(config);

    const defaultNetwork = cachedNetworks[0];

    appKitPromise = Promise.resolve(
      createAppKit({
        projectId,
        networks: cachedNetworks as [AppKitNetwork, ...AppKitNetwork[]],
        defaultNetwork,
        metadata: getMetadata(),
        manualWCControl: true,
        enableWalletGuide: false,
        showWallets: true,
        themeVariables: APPKIT_THEME,
      })
    );
  }

  const appKit = await appKitPromise;
  const requestedChainIds = new Set([...chains, ...(optionalChains ?? [])].map(toNetworkId));

  if (requestedChainIds.size) {
    const requestedNetworks = Array.from(requestedChainIds)
      .map((id) => appKit.getCaipNetwork(namespace, id))
      .filter((network): network is NonNullable<typeof network> => Boolean(network));

    if (requestedNetworks.length) {
      appKit.setRequestedCaipNetworks(requestedNetworks, namespace);
    }
  }

  return appKit;
};

/**
 * Lazily creates (or reuses) an AppKit instance configured for the provided
 * WalletConnect namespace and returns a minimal modal bridge compatible with
 * the existing provider API.
 */
export const ensureWalletConnectModal = async (config: EnsureModalConfig): Promise<WalletConnectModal> => {
  const appKit = await ensureAppKit(config);
  const { namespace } = config;

  const subscribeModal: WalletConnectModal['subscribeModal'] = (callback) => {
    return appKit.subscribeState((state) => callback({ open: Boolean(state?.open) }));
  };

  const openModal: WalletConnectModal['openModal'] = async (options) => {
    await appKit.open({
      view: 'Connect',
      namespace,
      uri: options?.uri,
    });
  };

  const closeModal: WalletConnectModal['closeModal'] = async () => {
    await appKit.close();
  };

  return {
    openModal,
    closeModal,
    subscribeModal,
  };
};

/**
 * Clears the cached AppKit instance to ensure isolation between tests.
 */
export const resetWalletConnectModalCache = (): void => {
  appKitPromise = null;
  cachedProjectId = null;
  cachedNamespace = null;
  cachedNetworks = [];
};

import base64 from 'base-64';
import { saveAs } from 'file-saver';

import type { Nullable } from '@/types/common';

export enum IMAGE_EXTENSIONS {
  SVG = '.svg',
  PNG = '.png',
  JPEG = '.jpeg',
  WEBP = '.webp',
  GIF = '.gif',
}

export const IMAGE_MIME_TYPES = {
  [IMAGE_EXTENSIONS.SVG]: 'image/svg+xml',
  [IMAGE_EXTENSIONS.PNG]: 'image/png',
  [IMAGE_EXTENSIONS.JPEG]: 'image/jpeg',
  [IMAGE_EXTENSIONS.WEBP]: 'image/webp',
  [IMAGE_EXTENSIONS.GIF]: 'image/gif',
};

/** Converts a base64 data URI into a `Blob`. */
export const dataURItoBlob = (dataURI: string): Blob => {
  // convert base64 to raw binary data held in a string
  const byteString = atob(dataURI.split(',')[1]);

  // separate out the mime component
  const mimeString = dataURI.split(',')[0].split(':')[1].split(';')[0];

  // write the bytes of the string to an ArrayBuffer
  const arrayBuffer = new ArrayBuffer(byteString.length);
  const _ia = new Uint8Array(arrayBuffer);

  for (let i = 0; i < byteString.length; i++) {
    _ia[i] = byteString.charCodeAt(i);
  }

  const dataView = new DataView(arrayBuffer);
  const blob = new Blob([dataView], { type: mimeString });

  return blob;
};

/** Creates a `Blob` from an image URL by drawing it onto a canvas. */
export const createImageBlobByUrl = (url: string, mimeType: string): Promise<Blob> => {
  return new Promise((resolve, reject) => {
    const image = new Image();

    image.src = url;

    image.onload = () => {
      const { width, height } = image;
      const canvas = Object.assign(document.createElement('canvas'), { width, height });
      const context = canvas.getContext('2d');

      if (context !== null) {
        context.fillStyle = 'white';
        context.fillRect(0, 0, canvas.width, canvas.height);
        context.drawImage(image, 0, 0);

        const dataURI = canvas.toDataURL(mimeType);
        const blob = dataURItoBlob(dataURI);

        resolve(blob);
      } else {
        reject(new Error(''));
      }
    };

    image.onerror = (error) => reject(error);
  });
};

/** Serializes an SVG element into a standalone blob. */
export const createSvgBlob = (svgElement: SVGSVGElement): Blob => {
  const data = new XMLSerializer().serializeToString(svgElement);
  const blob = new Blob([data], { type: 'image/svg+xml' });

  return blob;
};

/**
 * Persists an SVG element to disk, optionally rasterizing to another format
 * before downloading.
 */
export const svgSaveAs = async (
  svgElement: SVGSVGElement,
  name: string,
  extension: IMAGE_EXTENSIONS = IMAGE_EXTENSIONS.SVG
): Promise<void> => {
  let blob = createSvgBlob(svgElement);

  if (extension !== IMAGE_EXTENSIONS.SVG) {
    const mimeType = IMAGE_MIME_TYPES[extension];
    const url = URL.createObjectURL(blob);

    blob = await createImageBlobByUrl(url, mimeType);

    URL.revokeObjectURL(url);
  }

  const filename = `${name}${extension}`;

  saveAs(blob, filename);
};

const ALLOWED_ICON_MIME_TYPES = new Set([
  'image/png',
  'image/jpeg',
  'image/webp',
  'image/gif',
  'image/svg+xml',
]);

const DATA_URI_REGEX = /^data:(image\/[a-z0-9+.-]+);base64,([A-Za-z0-9+/=]+)$/i;

const decodeBase64 = (value: string): string => {
  try {
    if (typeof atob === 'function') {
      return atob(value);
    }
  } catch (error) {
    console.error(error);
  }

  return base64.decode(value);
};

const encodeBase64 = (value: string): string => {
  try {
    if (typeof btoa === 'function') {
      return btoa(value);
    }
  } catch (error) {
    console.error(error);
  }

  return base64.encode(value);
};

const sanitizeElementAttributes = (element: Element): void => {
  Array.from(element.attributes).forEach((attribute) => {
    const name = attribute.name;
    const value = attribute.value || '';

    if (/^on/i.test(name) || value.trim().toLowerCase().startsWith('javascript:')) {
      element.removeAttribute(name);
    }
  });
};

const stripDisallowedSvgContent = (rawSvg: string): string | null => {
  if (typeof DOMParser === 'undefined') return null;

  const parser = new DOMParser();
  const document = parser.parseFromString(rawSvg, 'image/svg+xml');

  if (document.querySelector('parsererror')) return null;

  const root = document.documentElement;

  if (!root) return null;

  const disallowedSelectors = ['script', 'foreignObject'];
  disallowedSelectors.forEach((selector) => {
    document.querySelectorAll(selector).forEach((node) => node.parentNode?.removeChild(node));
  });

  const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);

  sanitizeElementAttributes(root);

  while (walker.nextNode()) {
    const element = walker.currentNode as Element;
    if (!element) continue;

    sanitizeElementAttributes(element);
  }

  root.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  if (!root.getAttribute('width')) {
    root.setAttribute('width', '80px');
  }
  if (!root.getAttribute('height')) {
    root.setAttribute('height', '80px');
  }

  return new XMLSerializer().serializeToString(document);
};

const sanitizeSvgDataUri = (dataUri: string): string => {
  const match = DATA_URI_REGEX.exec(dataUri);
  if (!match) return '';

  const [, mimeType, payload] = match;
  if (mimeType.toLowerCase() !== 'image/svg+xml') return '';

  try {
    const decodedSvg = decodeBase64(payload);
    const sanitizedSvg = stripDisallowedSvgContent(decodedSvg);

    if (!sanitizedSvg) return '';

    const base64SvgEncoded = encodeBase64(sanitizedSvg);
    return `data:image/svg+xml;base64,${base64SvgEncoded}`;
  } catch (error) {
    console.error(error);
    return '';
  }
};

const sanitizeDataUri = (dataUri: string): string => {
  const match = DATA_URI_REGEX.exec(dataUri);
  if (!match) return '';

  const [, mimeType] = match;
  const normalizedMime = mimeType.toLowerCase();

  if (!ALLOWED_ICON_MIME_TYPES.has(normalizedMime)) {
    return '';
  }

  if (normalizedMime === 'image/svg+xml') {
    return sanitizeSvgDataUri(dataUri);
  }

  return dataUri;
};

/**
 * Ensures the provided icon URL or data URI is safe to embed. Returns an empty
 * string when the input is considered unsafe.
 */
export const sanitizeIconSource = (icon: Nullable<string>): string => {
  if (!icon) return '';

  const trimmed = icon.trim();

  if (trimmed.startsWith('data:')) {
    return sanitizeDataUri(trimmed);
  }

  try {
    const url = new URL(trimmed);
    if (url.protocol !== 'https:') return '';
    if (/["'()\s]/.test(trimmed)) return '';

    return url.href;
  } catch (error) {
    console.error(error);
    return '';
  }
};

/**
 * Formats a safe CSS `url()` string escaping troublesome characters.
 */
export const buildCssUrl = (url: string): string => {
  const escaped = url.replace(/["\\\n\r]/g, (char) => `\\${char}`);
  const parenthesesEscaped = escaped.replace(/\)/g, '\\)');

  return `url("${parenthesesEscaped}")`;
};

/** Transform svg data URIs into base64 encoded PNG icons. */
export async function getBase64Icon(icon: string): Promise<string> {
  const safeIcon = sanitizeIconSource(icon);

  if (!safeIcon) return '';
  if (safeIcon.startsWith('data:image/png;base64')) return safeIcon;
  if (safeIcon.startsWith('data:image/svg+xml;base64')) {
    return base64SvgToBase64Png(safeIcon);
  }

  if (safeIcon.startsWith('https://')) {
    return safeIcon;
  }

  return '';
}

/** Helper that renders a base64-encoded SVG onto a canvas and returns a PNG. */
function base64SvgToBase64Png(imgsrc: string): Promise<string> {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement('canvas');

    canvas.setAttribute('width', '80');
    canvas.setAttribute('height', '80');

    const context = canvas.getContext('2d');

    const image = new Image();
    image.src = imgsrc;

    image.onload = function () {
      try {
        if (context) {
          context.drawImage(image, 0, 0);
          const base64PNG = canvas.toDataURL('image/png');
          resolve(base64PNG);
        }
      } catch (e) {
        reject(e);
      }
    };
  });
}

import type { Blacklist, WhitelistArrayItem } from '@sora-substrate/sdk/build/assets/types';

const MAX_SYMBOL_LENGTH = 32;
const MAX_NAME_LENGTH = 128;
const MAX_ADDRESS_LENGTH = 256;
const MAX_ICON_LENGTH = 1024;
const CONTROL_CHARS_REGEXP = /[\u0000-\u001F\u007F]/g;
const FORBIDDEN_HTML_CHARS_REGEXP = /[<>]/g;
const ALLOWED_ICON_PROTOCOLS = new Set(['http:', 'https:', 'ipfs:', 'data:']);

const sanitizeText = (value: unknown, maxLength: number): string => {
  if (typeof value !== 'string') return '';

  return value
    .replace(CONTROL_CHARS_REGEXP, '')
    .replace(FORBIDDEN_HTML_CHARS_REGEXP, '')
    .trim()
    .slice(0, maxLength);
};

const sanitizeAddress = (value: unknown): string => {
  return sanitizeText(value, MAX_ADDRESS_LENGTH);
};

const sanitizeSymbol = (value: unknown): string => {
  return sanitizeText(value, MAX_SYMBOL_LENGTH);
};

const sanitizeName = (value: unknown): string => {
  return sanitizeText(value, MAX_NAME_LENGTH);
};

const sanitizeIcon = (value: unknown): string => {
  const icon = sanitizeText(value, MAX_ICON_LENGTH);
  if (!icon) return '';

  if (icon.startsWith('/') || icon.startsWith('./') || icon.startsWith('../')) return icon;
  if (icon.startsWith('data:image/')) return icon;

  try {
    const parsed = new URL(icon, 'https://placeholder.invalid');
    return ALLOWED_ICON_PROTOCOLS.has(parsed.protocol) ? icon : '';
  } catch {
    return '';
  }
};

const sanitizeDecimals = (value: unknown): number | null => {
  if (typeof value === 'number' && Number.isFinite(value)) {
    const rounded = Math.trunc(value);
    return rounded >= 0 && rounded <= 30 ? rounded : null;
  }

  if (typeof value === 'string' && value.trim()) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) {
      const rounded = Math.trunc(parsed);
      return rounded >= 0 && rounded <= 30 ? rounded : null;
    }
  }

  return null;
};

const toPlainObject = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;

  const proto = Object.getPrototypeOf(value);
  if (proto !== Object.prototype && proto !== null) return null;

  return value as Record<string, unknown>;
};

export const sanitizeWhitelistPayload = (payload: string): WhitelistArrayItem[] => {
  let parsed: unknown;

  try {
    parsed = JSON.parse(payload);
  } catch (error) {
    console.error('[whitelist] Unable to parse whitelist payload.', error);
    return [];
  }

  if (!Array.isArray(parsed)) {
    console.warn('[whitelist] Payload is not an array.');
    return [];
  }

  const sanitized: WhitelistArrayItem[] = [];

  parsed.forEach((item, index) => {
    const candidate = toPlainObject(item);

    if (!candidate) {
      console.warn(`[whitelist] Skipping entry at index ${index} due to invalid structure.`);
      return;
    }

    const address = sanitizeAddress(candidate.address);
    const symbol = sanitizeSymbol(candidate.symbol);
    const name = sanitizeName(candidate.name);
    const icon = sanitizeIcon(candidate.icon);
    const decimals = sanitizeDecimals(candidate.decimals);

    if (!address || !symbol || !name || decimals === null) {
      console.warn(`[whitelist] Skipping entry at index ${index} due to missing required fields.`);
      return;
    }

    sanitized.push({ address, symbol, name, icon, decimals });
  });

  return sanitized;
};

export const sanitizeNftBlacklistPayload = (payload: string): Blacklist => {
  const trimmedPayload = typeof payload === 'string' ? payload.trim() : '';

  if (!trimmedPayload) {
    console.warn('[nft-blacklist] Payload is empty.');
    return [];
  }

  if (!trimmedPayload.startsWith('[')) {
    console.warn('[nft-blacklist] Payload is not an array.');
    return [];
  }

  let parsed: unknown;

  try {
    parsed = JSON.parse(trimmedPayload);
  } catch (error) {
    console.warn('[nft-blacklist] Unable to parse blacklist payload.', error);
    return [];
  }

  if (!Array.isArray(parsed)) {
    console.warn('[nft-blacklist] Payload is not an array.');
    return [];
  }

  const sanitized: string[] = [];

  parsed.forEach((item, index) => {
    const address = sanitizeAddress(item);
    if (!address) {
      console.warn(`[nft-blacklist] Skipping entry at index ${index} due to invalid address.`);
      return;
    }

    sanitized.push(address);
  });

  return sanitized;
};

import { AES, HmacSHA256, enc } from 'crypto-js';
import crypto from 'crypto-js';
import { Cosigners, EncryptedKeyForCosigner, FinalEncryptedStructure } from '@sora-substrate/sdk';
import { u8aToHex } from '@polkadot/util';
import { sr25519Agreement } from '@polkadot/util-crypto';

type StorageNamespaces = {
  current: string;
  legacy: string[];
};

const LEGACY_KEY = 'U2FsdGVkX18ZUVvShFSES21qHsQEqZXMxQ9zgHy';
const MASTER_KEY_STORAGE = 'sora.crypto.masterKey';
const SECRET_LENGTH = 32;
const ENCRYPTION_PREFIX = 'psk1:';

let cachedMasterKey: string | null = null;

const isBrowserStorageAvailable = (): boolean => {
  try {
    return typeof window !== 'undefined' && !!window.localStorage;
  } catch {
    return false;
  }
};

const toBase64 = (bytes: Uint8Array): string => crypto.enc.Base64.stringify(crypto.lib.WordArray.create(bytes));

const wordArrayToUint8Array = (wordArray: crypto.lib.WordArray): Uint8Array => {
  const { words, sigBytes } = wordArray;
  const result = new Uint8Array(sigBytes);

  for (let i = 0; i < sigBytes; i += 1) {
    const word = words[i >>> 2];
    result[i] = (word >>> (24 - (i % 4) * 8)) & 0xff;
  }

  return result;
};

const generateSecret = (): string => {
  const bytes =
    typeof globalThis !== 'undefined' && globalThis.crypto?.getRandomValues
      ? (() => {
          const array = new Uint8Array(SECRET_LENGTH);
          globalThis.crypto.getRandomValues(array);
          return array;
        })()
      : wordArrayToUint8Array(crypto.lib.WordArray.random(SECRET_LENGTH));

  return toBase64(bytes);
};

const readStoredSecret = (): string | null => {
  if (!isBrowserStorageAvailable()) return null;
  try {
    return window.localStorage.getItem(MASTER_KEY_STORAGE);
  } catch {
    return null;
  }
};

const persistSecret = (secret: string): void => {
  if (!isBrowserStorageAvailable()) return;
  try {
    window.localStorage.setItem(MASTER_KEY_STORAGE, secret);
  } catch {
    // Swallow quota/security errors – the secret will be regenerated next time.
  }
};

const getMasterKey = (): string => {
  if (cachedMasterKey) {
    return cachedMasterKey;
  }

  const stored = readStoredSecret();
  if (stored) {
    cachedMasterKey = stored;
    return stored;
  }

  const generated = generateSecret();
  persistSecret(generated);
  cachedMasterKey = generated;
  return generated;
};

const encryptWithKey = (message: string, key: string): string => AES.encrypt(message, key).toString();

const decryptWithKey = (message: string, key: string): string => {
  const decrypted = AES.decrypt(message, key);
  if (!decrypted || typeof decrypted.sigBytes !== 'number' || decrypted.sigBytes <= 0) {
    return '';
  }

  try {
    return decrypted.toString(enc.Utf8);
  } catch {
    return '';
  }
};

const hmacWithKey = (message: string, key: string): string => HmacSHA256(message, key).toString();

export const encrypt = (message: string): string => {
  const cipher = encryptWithKey(message, getMasterKey());
  return `${ENCRYPTION_PREFIX}${cipher}`;
};

export const decrypt = (message: string): string => {
  if (!message) return '';

  const isReadable = (value: string): boolean => /^[\x20-\x7E]*$/.test(value);

  if (message.startsWith(ENCRYPTION_PREFIX)) {
    const payload = message.slice(ENCRYPTION_PREFIX.length);
    return decryptWithKey(payload, getMasterKey());
  }

  try {
    const primary = decryptWithKey(message, getMasterKey());
    if (primary && isReadable(primary)) {
      return primary;
    }
  } catch {
    // fall through to legacy key
  }

  return decryptWithKey(message, LEGACY_KEY);
};

export const toHmacSHA256 = (message: string): string => hmacWithKey(message, getMasterKey());

export const deriveAddressNamespaces = (message: string): StorageNamespaces => {
  const current = toHmacSHA256(message);
  const legacyHash = hmacWithKey(message, LEGACY_KEY);
  const legacy = legacyHash !== current ? [legacyHash] : [];

  return { current, legacy };
};

export class CryptoModule {
  combineSharedSecret(publicKey: Uint8Array, secretKey: Uint8Array): Uint8Array {
    return sr25519Agreement(secretKey, publicKey);
  }

  _encryptMessage(keyHex: string, message: string): { encryptedData: string; iv: string } {
    const iv = crypto.lib.WordArray.random(16);
    const encrypted = crypto.AES.encrypt(message, crypto.enc.Hex.parse(keyHex), {
      iv: iv,
      mode: crypto.mode.CBC,
      padding: crypto.pad.Pkcs7,
    });

    return {
      encryptedData: encrypted.toString(),
      iv: iv.toString(crypto.enc.Hex),
    };
  }

  _decryptMessage(keyHex: string, encryptedData: string, iv: string): string {
    const decrypted = crypto.AES.decrypt(encryptedData, crypto.enc.Hex.parse(keyHex), {
      iv: crypto.enc.Hex.parse(iv),
      mode: crypto.mode.CBC,
      padding: crypto.pad.Pkcs7,
    });
    return decrypted.toString(crypto.enc.Utf8);
  }

  encryptBySigner(callDataStr: string, cosigners: Cosigners, secretKeyOfSigner: Uint8Array) {
    const symmetricKey = crypto.lib.WordArray.random(32).toString(crypto.enc.Hex);

    // Encrypt callData with symmetricKey
    const { encryptedData: encryptedCallData, iv: dataIv } = this._encryptMessage(symmetricKey, callDataStr);
    const encryptedKeys: { [cosignerAddress: string]: EncryptedKeyForCosigner } = {};
    for (const [address, cosignerPublicKey] of Object.entries(cosigners)) {
      const sharedSecret = this.combineSharedSecret(cosignerPublicKey, secretKeyOfSigner);
      const sharedSecretHex = u8aToHex(sharedSecret).replace(/^0x/, '');

      const { encryptedData: encryptedSymKey, iv: symKeyIv } = this._encryptMessage(sharedSecretHex, symmetricKey);

      encryptedKeys[address] = {
        encryptedKey: encryptedSymKey,
        iv: symKeyIv,
      };
    }
    const finalEncrypted: FinalEncryptedStructure = {
      encryptedData: encryptedCallData,
      dataIv: dataIv,
      encryptedKeys: encryptedKeys,
    };
    return finalEncrypted;
  }

  decryptForCosigner(
    cosignerAddress: string,
    encryptorPublicKey: Uint8Array,
    finalEncrypted: FinalEncryptedStructure,
    secretKeyOfSigner: Uint8Array
  ): any {
    const cosignerData = finalEncrypted.encryptedKeys[cosignerAddress];

    if (!cosignerData) {
      throw new Error(`No encrypted data found for cosigner: ${cosignerAddress}`);
    }

    // Generate the shared secret using the cosigner's secret key and the encryptor's public key
    const sharedSecret = this.combineSharedSecret(encryptorPublicKey, secretKeyOfSigner);
    const sharedSecretHex = u8aToHex(sharedSecret).replace(/^0x/, '');

    // Decrypt the symmetric key for the cosigner
    const symmetricKey = this._decryptMessage(sharedSecretHex, cosignerData.encryptedKey, cosignerData.iv);

    // Decrypt the main call data
    const decryptedCallDataStr = this._decryptMessage(
      symmetricKey,
      finalEncrypted.encryptedData,
      finalEncrypted.dataIv
    );

    // Parse and return the decrypted call data
    return JSON.parse(decryptedCallDataStr);
  }
}

import { map, Observable, combineLatest, distinctUntilChanged } from 'rxjs';
import { assert } from '@polkadot/util';
import { FPNumber, NumberLike } from '@sora-substrate/math';
import { PriceVariant, QuotePayload } from '@sora-substrate/liquidity-proxy';
import { getAveragePrice } from '@sora-substrate/liquidity-proxy';
import type { BandBandRate, KensetsuCollateralInfo, KensetsuCollateralizedDebtPosition } from '@polkadot/types/lookup';
import type { Vec, u128, Option } from '@polkadot/types-codec';
import type { Percent } from '@polkadot/types/interfaces/runtime';

import { Messages } from '../logger';
import { Operation } from '../types';
import { toAssetId } from '../assets';
import { DAI, KUSD, KXOR } from '../assets/consts';
import { VaultTypes } from './consts';
