const WALLET_DEFAULT_ROUTE = WALLET_CONSTS.RouteNames.Wallet;

const router = createRouter({
  history: createWebHashHistory(),
  routes,
});

router.beforeEach((to: RouteLocationNormalized, from: RouteLocationNormalized, next) => {
  const prev = from.name as Nullable<PageNames>;
  const current = to.name as PageNames;
  const routerStore = useRouterStore();
  const walletStore = useWalletStore();
  const bridgeHistoryStore = useBridgeHistoryStore();
  const setRoute = (name: PageNames, withNext = true) => {
    const params = { prev, current: name };
    routerStore.setRoute(params);
    syncLegacyRoute(params);
    next(withNext ? { name } : undefined);
    updateDocumentTitle(to);
  };
  const isLoggedIn = walletStore.isLoggedIn;
  const isInvitationRoute = to.matched.some((record) => record.meta.isInvitationRoute);
  const isRequiresAuth = to.matched.some((record) => record.meta.requiresAuth);

  if (shouldResetBridgeHistory(prev, current)) {
    bridgeHistoryStore.resetHistoryPage();
  }

  const invitationDecision = resolveInvitationDecision({
    isInvitationRoute,
    referrerParam: to.params.referrerAddress,
    isLoggedIn,
    validateAddress: isValidWalletAddress,
  });

  if (invitationDecision.persistReferral) {
    persistReferralAddress(invitationDecision.persistReferral);
  }

  if (invitationDecision.redirect) {
    setRoute(invitationDecision.redirect.name, invitationDecision.redirect.callNext);
    return;
  }

  const authRedirect = resolveAuthRedirect({
    requiresAuth: isRequiresAuth,
    current,
    isLoggedIn,
  });

  if (authRedirect) {
    setRoute(authRedirect.name, authRedirect.callNext);
    return;
  }
  setRoute(current, false);
});

/**
 * Use this function instead just `router.push` when page loading is required.
 *
 * It checks wallet routing, page loading and the current route.
 * if the current route isn't the same as param, then it will wait for `router.push`
 */
const goTo = async (name: PageNames): Promise<void> => {
  const current = router.currentRoute.value?.name as PageNames | undefined;
  const routerStore = useRouterStore();
  const walletStore = useWalletStore();
  if (name === PageNames.Wallet) {
    if (!walletStore.isLoggedIn) {
      routerStore.navigate({ name: WALLET_CONSTS.RouteNames.WalletConnection });
    } else if (routerStore.current !== WALLET_DEFAULT_ROUTE) {
      routerStore.navigate({ name: WALLET_DEFAULT_ROUTE });
    }
  }
  if (current === name) {
    return;
  }
  try {
    routerStore.setLoading(true);
    setLegacyRouterLoading(true);
    await router.push({ name });
  } finally {
    routerStore.setLoading(false);
    setLegacyRouterLoading(false);
  }
};

export { lazyComponent, lazyView, goTo };
export default router;

import { defineModule } from 'direct-vuex';

import { localActionContext, localGetterContext } from '@/store';
import { Module } from '@/store/consts';
import { useAssetsStore } from '@/stores/assets';
import { XOR } from '@sora-substrate/sdk/build/assets/consts';

import type { Asset, RegisteredAccountAsset } from '@sora-substrate/sdk/build/assets/types';
import type { Nullable } from '@/types/common';

import type { AssetsState, BridgeRegisteredAsset } from './types';

const buildInitialState = (): AssetsState => ({
  registeredAssets: {},
  registeredAssetsFetching: false,
});

const state: AssetsState = buildInitialState();

const getAssetsStore = () => useAssetsStore();

const syncStateFromPinia = (storeState: AssetsState): void => {
  const assetsStore = getAssetsStore();

  storeState.registeredAssets = Object.freeze({ ...assetsStore.registeredAssets });
  storeState.registeredAssetsFetching = assetsStore.registeredAssetsFetching;
};

const getters = {
  assetDataByAddress:
    (_storeState: AssetsState) =>
    (address?: Nullable<string>): Nullable<RegisteredAccountAsset> => {
      if (!address) return null;

      return (getAssetsStore().assetDataByAddress(address) as Nullable<RegisteredAccountAsset>) ?? null;
    },
  whitelistAssets(): Array<Asset> {
    return getAssetsStore().whitelistAssets;
  },
  xor(): Nullable<RegisteredAccountAsset> {
    return (getAssetsStore().assetDataByAddress(XOR.address) as Nullable<RegisteredAccountAsset>) ?? null;
  },
  registeredAssets: (storeState: AssetsState): AssetsState['registeredAssets'] => storeState.registeredAssets,
  registeredAssetsFetching: (storeState: AssetsState): boolean => storeState.registeredAssetsFetching,
};

const mutations = {
  setRegisteredAssets(storeState: AssetsState, assets: Record<string, BridgeRegisteredAsset> = {}): void {
    const assetsStore = getAssetsStore();
    assetsStore.setRegisteredAssets(assets);
    syncStateFromPinia(storeState);
  },
  setRegisteredAssetsFetching(storeState: AssetsState, value: boolean): void {
    const assetsStore = getAssetsStore();
    assetsStore.setRegisteredAssetsFetching(value);
    syncStateFromPinia(storeState);
  },
  reset(storeState: AssetsState): void {
    const assetsStore = getAssetsStore();
    assetsStore.reset();
    Object.assign(storeState, buildInitialState());
    syncStateFromPinia(storeState);
  },
};

const actions = {
  async getRegisteredAssets(context): Promise<void> {
    const { state: moduleState } = assetsActionContext(context);
    const assetsStore = getAssetsStore();

    assetsStore.setRegisteredAssetsFetching(true);
    syncStateFromPinia(moduleState);

    try {
      await assetsStore.getRegisteredAssets();
    } finally {
      syncStateFromPinia(moduleState);
    }
  },
  async updateRegisteredAssets(
    context,
    assets?: Record<string, BridgeRegisteredAsset>
  ): Promise<void> {
    const { state: moduleState } = assetsActionContext(context);
    const assetsStore = getAssetsStore();

    if (assets) {
      assetsStore.setRegisteredAssets(assets);
      syncStateFromPinia(moduleState);
    }

    assetsStore.setRegisteredAssetsFetching(true);
    syncStateFromPinia(moduleState);

    try {
      await assetsStore.updateRegisteredAssets();
    } finally {
      syncStateFromPinia(moduleState);
    }
  },
};

const assets = defineModule({
  namespaced: true,
  state,
  getters,
  mutations,
  actions,
});

const assetsGetterContext = (args: [any, any, any, any]) => localGetterContext(args, Module.Assets, assets);
const assetsActionContext = (context: any) => localActionContext(context, Module.Assets, assets);

export { assetsGetterContext, assetsActionContext };
export default assets;

import { defineStore } from 'pinia';

import { withLegacyStore } from '@/utils/legacy-store';
import { trackEvent } from '@/utils/telemetry';

import { enterPiniaSync, enterLegacySync, isLegacySyncing, isPiniaSyncing, leaveLegacySync, leavePiniaSync } from './sync';

type BridgeHistoryState = {
  historyPage: number;
  historyId: string;
};

const buildInitialState = (): BridgeHistoryState => ({
  historyPage: 1,
  historyId: '',
});

const normalizePage = (page?: number): number => {
  const parsed = Number(page);

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return 1;
  }

  return Math.floor(parsed);
};

const normalizeId = (id?: string): string => (typeof id === 'string' ? id : '');

const warn = (message: string): void => {
  console.warn(`[bridge-history] ${message}`);
};

export const useBridgeHistoryStore = defineStore('bridgeHistory', {
  state: (): BridgeHistoryState => buildInitialState(),
  actions: {
    setHistoryPage(page?: number): void {
      const nextPage = normalizePage(page);
      this.historyPage = nextPage;
      trackEvent('bridge.pinia.historyPage.changed', { page: nextPage });

      if (isLegacySyncing()) {
        return;
      }

      const committed = withLegacyStore((store) => {
        const mutation = store?.commit?.bridge?.setHistoryPage;

        if (typeof mutation !== 'function') {
          warn('setHistoryPage mutation missing');
          return undefined;
        }

        enterPiniaSync();
        try {
          mutation(nextPage);
        } finally {
          leavePiniaSync();
        }

        return true;
      });

      if (!committed) {
        warn('unable to sync historyPage to legacy store');
      }
    },
    resetHistoryPage(): void {
      this.setHistoryPage(1);
    },
    syncHistoryPageFromLegacy(page?: number): void {
      const nextPage = normalizePage(page);

      if (this.historyPage === nextPage) {
        return;
      }

      enterLegacySync();
      try {
        this.historyPage = nextPage;
      } finally {
        leaveLegacySync();
      }
    },
    setHistoryId(id?: string): void {
      const nextId = normalizeId(id);
      this.historyId = nextId;

      if (isLegacySyncing()) {
        return;
      }

      const committed = withLegacyStore((store) => {
        const mutation = store?.commit?.bridge?.setHistoryId;

        if (typeof mutation !== 'function') {
          warn('setHistoryId mutation missing');
          return undefined;
        }

        enterPiniaSync();
        try {
          mutation(nextId);
        } finally {
          leavePiniaSync();
        }

        return true;
      });

      if (!committed) {
        warn('unable to sync historyId to legacy store');
      }
    },
    syncHistoryIdFromLegacy(id?: string): void {
      const nextId = normalizeId(id);

      if (this.historyId === nextId) {
        return;
      }

      enterLegacySync();
      try {
        this.historyId = nextId;
      } finally {
        leaveLegacySync();
      }
    },
  },
});

