import { ensureAppKit } from './appkit';
import {
  getWalletConnectProjectId as resolveWalletConnectProjectId,
  resetWalletConnectProjectIdCache,
} from './walletconnectProject';

const DEFAULT_CHAIN_ID = 1;
const Z_INDEX_VARIABLE = '--wcm-z-index';

const withDefaultChainProps = (chainProps?: ChainsProps): ChainsProps => {
  if (chainProps && ('chains' in chainProps ? chainProps.chains?.length : chainProps.optionalChains?.length)) {
    return chainProps;
  }
  return { chains: [DEFAULT_CHAIN_ID] };
};

const getProbeChainId = (chainProps: ChainsProps): number => {
  if ('chains' in chainProps && Array.isArray(chainProps.chains) && chainProps.chains.length > 0) {
    return chainProps.chains[0] ?? DEFAULT_CHAIN_ID;
  }
  if ('optionalChains' in chainProps && Array.isArray(chainProps.optionalChains) && chainProps.optionalChains.length > 0) {
    return chainProps.optionalChains[0] ?? DEFAULT_CHAIN_ID;
  }
  return DEFAULT_CHAIN_ID;
};

const attachModal = (provider: EthereumProvider, modal: AppKit): void => {
  Object.assign(provider, { modal });
};

export { resetWalletConnectProjectIdCache };

export const getWalletConnectProjectId = (): Promise<string> => {
  return resolveWalletConnectProjectId();
};

export class WcEthereumProvider extends EthereumProvider {
  /**
   * "Init" is overrided to return the instance of this child class
   */
  static override async init(opts: EthereumProviderOptions): Promise<WcEthereumProvider> {
    const provider = new WcEthereumProvider();
    await provider.initialize(opts);
    return provider;
  }

  protected _session!: SessionTypes.Struct | undefined;

  override get session(): SessionTypes.Struct | undefined {
    return this._session;
  }

  protected async setAppSession(session: SessionTypes.Struct | undefined): Promise<void> {
    if (!session) return;
    this._session = session;
  }

  protected async restoreAppSession(): Promise<void> {
    if (this.session) return;

    const chainId = this.formatChainId(this.chainId);
    const sessions = this.signer.client.session.values;

    for (const session of sessions) {
      const sessionData = session.namespaces[this.namespace];

      if (!sessionData) continue;

      const sessionChains = sessionData.chains;

      if (!(Array.isArray(sessionChains) && sessionChains.includes(chainId))) continue;

      const pairingTopic = session.pairingTopic;
      const expiry = Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 7;
      try {
        console.info(`[${this.constructor.name}]: active pairing found: "${pairingTopic}"`);
        await this.signer.client.core.pairing.activate({ topic: pairingTopic });
        console.info(`[${this.constructor.name}]: pairing activated: "${pairingTopic}"`);
        await this.signer.client.core.pairing.updateExpiry({ topic: pairingTopic, expiry });
        console.info(`[${this.constructor.name}]: pairing expiry updated: "${pairingTopic}"`);
        this.setAppSession(session);
        return;
      } catch {
        console.info(
          `[${this.constructor.name}]: pairing not active: "${pairingTopic}". Session "${session.topic}" deleted.`
        );
        this.signer.client.disconnect({
          topic: session.topic,
          reason: {
            code: 6000, // https://specs.walletconnect.com/2.0/specs/clients/sign/error-codes#reason
            message: 'Disconnected by dApp',
          },
        });
      }
    }
  }

  public override async connect(opts?: ConnectOps): Promise<void> {
    // eslint-disable-next-line
    await new Promise<void>(async (resolve, reject) => {
      const unsub = this.modal?.subscribeModal((state: { open: boolean }) => {
        // This is the fix of modal close handler to check only ethereum session
        if (
          !state.open &&
          (!this.signer.session || !Object.keys(this.signer.session.namespaces).includes(this.namespace))
        ) {
          unsub();
          this.signer.abortPairingAttempt();
          reject(new Error('Connection request reset. Please try again.'));
        }
      });

      try {
        await this.restoreAppSession();

        if (!this.session) {
          await super.connect(opts);

          this.setAppSession(this.signer.session);
        }

        resolve();
      } catch (error) {
        await this.signer.disconnect();
        reject(error);
      }
    });
  }
}

export const checkWalletConnectAvailability = async (chainProps?: ChainsProps): Promise<void> => {
  const resolvedProps = withDefaultChainProps(chainProps);
  const projectId = await resolveWalletConnectProjectId();
  const chainIdCheck = getProbeChainId(resolvedProps);
  const url = `https://rpc.walletconnect.com/v1/?chainId=eip155:${chainIdCheck}&projectId=${projectId}`;

  await fetch(url, {
    method: 'POST',
    body: JSON.stringify({ id: 1, jsonrpc: '2.0', method: 'test', params: [] }),
  });
};

export const getWcEthereumProvider = async (
  chainProps?: ChainsProps
): Promise<InstanceType<typeof EthereumProvider>> => {
  try {
    const resolvedProps = withDefaultChainProps(chainProps);

    await checkWalletConnectAvailability(resolvedProps);

    const [projectId, appKit] = await Promise.all([
      resolveWalletConnectProjectId(),
      ensureAppKit(resolvedProps),
    ]);

    const ethereumProvider = await WcEthereumProvider.init({
      projectId,
      showQrModal: true,
      qrModalOptions: {
        themeVariables: {
          [Z_INDEX_VARIABLE]: '9999',
        },
      },
      ...resolvedProps,
    });

    attachModal(ethereumProvider, appKit);

    return ethereumProvider;
  } catch (error) {
    console.error(error);
    throw new Error('provider.messages.notAvailable');
  }
};

type TelemetryPayload = Record<string, unknown>;

type TelemetryClient = {
  track?: (event: string, payload?: TelemetryPayload) => void;
};

const getTelemetryClient = (): TelemetryClient | undefined => {
  if (typeof globalThis === 'undefined') return undefined;

  const scope = globalThis as Record<string, unknown>;
  const client =
    (scope.__PS_TELEMETRY__ as TelemetryClient | undefined) ??
    (scope.__PS_ANALYTICS__ as TelemetryClient | undefined);

  if (client && typeof client.track === 'function') {
    return client;
  }

  return undefined;
};

export const trackEvent = (event: string, payload: TelemetryPayload = {}): void => {
  try {
    const client = getTelemetryClient();
    if (client?.track) {
      client.track(event, payload);
      return;
    }
  } catch (error) {
    console.warn('[telemetry] trackEvent failed', error);
    return;
  }

  if (typeof console !== 'undefined' && typeof console.debug === 'function') {
    console.debug(`[telemetry] ${event}`, payload);
  }
};

import { FPNumber } from '@sora-substrate/sdk';

import { formatAmountWithSuffix, formatDecimalPlaces, sortPools } from '@/utils';

import type { PoolData } from '@/indexer/queries/pool/pools';
import type { AmountWithSuffix } from '@/types/formats';
import type { RegisteredAccountAsset } from '@sora-substrate/sdk/build/assets/types';
import type { AccountLiquidity } from '@sora-substrate/sdk/build/poolXyk/types';

export type PoolTokenRow = {
  asset: RegisteredAccountAsset;
  balance: string;
};

export type PoolExploreTableItem = {
  name: string;
  baseAsset: RegisteredAccountAsset;
  targetAsset: RegisteredAccountAsset;
  priceUSD: number;
  priceUSDFormatted: string;
  apy: number;
  apyFormatted: string;
  tvl: number;
  tvlFormatted: AmountWithSuffix;
  isAccountItem: boolean;
  poolTokens: PoolTokenRow[];
  accountTokens: PoolTokenRow[];
};

type BuildPoolTableItemsOptions = {
  pools: readonly PoolData[];
  accountLiquidity: readonly AccountLiquidity[];
  getAsset: (address?: string) => Nullable<RegisteredAccountAsset>;
};

const formatAccountToken = (value?: string): string => {
  return formatDecimalPlaces(FPNumber.fromCodecValue(value ?? 0));
};

const findAccountPool = (
  accountLiquidity: readonly AccountLiquidity[],
  baseAssetId: string,
  targetAssetId: string
): Nullable<AccountLiquidity> => {
  return (
    accountLiquidity.find(
      (liquidity) => liquidity.firstAddress === baseAssetId && liquidity.secondAddress === targetAssetId
    ) ?? null
  );
};

/**
 * Normalises indexer pool entries into rows consumed by the Pools explore table.
 */
export function buildPoolTableItems({
  pools,
  accountLiquidity,
  getAsset,
}: BuildPoolTableItemsOptions): PoolExploreTableItem[] {
  const items = pools.reduce<PoolExploreTableItem[]>((buffer, pool) => {
    const baseAsset = getAsset(pool.baseAssetId);
    const targetAsset = getAsset(pool.targetAssetId);

    if (!baseAsset || !targetAsset) return buffer;

    const name = `${baseAsset.symbol}-${targetAsset.symbol}`;
    const baseAssetReserves = FPNumber.fromCodecValue(pool.baseAssetReserves ?? 0, baseAsset.decimals);
    const targetAssetReserves = FPNumber.fromCodecValue(pool.targetAssetReserves ?? 0, targetAsset.decimals);
    const tvlUSD = targetAssetReserves.mul(pool.priceUSD).mul(FPNumber.TWO);

    const accountPool = findAccountPool(accountLiquidity, baseAsset.address, targetAsset.address);

    const poolTokens: PoolTokenRow[] = [
      {
        asset: baseAsset,
        balance: formatDecimalPlaces(baseAssetReserves),
      },
      {
        asset: targetAsset,
        balance: formatDecimalPlaces(targetAssetReserves),
      },
    ];

    const accountTokens: PoolTokenRow[] = [
      {
        asset: baseAsset,
        balance: formatAccountToken(accountPool?.firstBalance),
      },
      {
        asset: targetAsset,
        balance: formatAccountToken(accountPool?.secondBalance),
      },
    ];

    buffer.push({
      name,
      baseAsset,
      targetAsset,
      priceUSD: pool.priceUSD.toNumber(),
      priceUSDFormatted: pool.priceUSD.toLocaleString(),
      apy: pool.apy.toNumber(),
      apyFormatted: formatDecimalPlaces(pool.apy, true),
      tvl: tvlUSD.toNumber(),
      tvlFormatted: formatAmountWithSuffix(tvlUSD),
      isAccountItem: Boolean(accountPool),
      poolTokens,
      accountTokens,
    });

    return buffer;
  }, []);

  return [...items].sort((a, b) =>
    sortPools(
      { baseAsset: a.baseAsset, poolAsset: a.targetAsset },
      { baseAsset: b.baseAsset, poolAsset: b.targetAsset }
    )
  );
}

/**
 * Applies the legacy Explore search semantics to pool table rows.
 */
export function filterPoolTableItems(
  items: readonly PoolExploreTableItem[],
  search: string
): readonly PoolExploreTableItem[] {
  const normalized = search.toLowerCase().trim();

  if (!normalized) return items;

  const matchesAsset = (asset?: RegisteredAccountAsset | null): boolean => {
    if (!asset) return false;
    return (
      asset.name?.toLowerCase?.().includes(normalized) ||
      asset.symbol?.toLowerCase?.().includes(normalized) ||
      asset.address?.toLowerCase?.() === normalized
    );
  };

  return items.filter((item) => {
    return (
      item.name.toLowerCase().includes(normalized) ||
      matchesAsset(item.baseAsset) ||
      matchesAsset(item.targetAsset)
    );
  });
}

