let originalClientWidth: PropertyDescriptor | undefined;
let originalInnerWidth: PropertyDescriptor | undefined;

beforeAll(() => {
  originalClientWidth = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'clientWidth');
  Object.defineProperty(HTMLElement.prototype, 'clientWidth', {
    configurable: true,
    get() {
      return 2200;
    },
  });

  originalInnerWidth = Object.getOwnPropertyDescriptor(window, 'innerWidth');
  Object.defineProperty(window, 'innerWidth', {
    configurable: true,
    writable: true,
    value: 2200,
  });
});

afterAll(() => {
  if (originalClientWidth) {
    Object.defineProperty(HTMLElement.prototype, 'clientWidth', originalClientWidth);
  }
  if (originalInnerWidth) {
    Object.defineProperty(window, 'innerWidth', originalInnerWidth);
  }
});

const defaultLayouts: ResponsiveLayouts = {
  lg: [
    { i: 'widget-1', x: 0, y: 0, w: 6, h: 4 } as LayoutWidget,
    { i: 'widget-2', x: 6, y: 0, w: 6, h: 4 } as LayoutWidget,
  ],
};

const baseModel = {
  'widget-1': true,
  'widget-2': false,
};

let Grid: typeof import('@/components/shared/Widget/Grid.vue').default;

const mountGrid = async (props?: Record<string, unknown>) => {
  const wrapper = mount(Grid, {
    props: {
      gridId: 'test-grid',
      defaultLayouts,
      value: baseModel,
      ...props,
    },
  });

  await flushPromises();
  return wrapper;
};

describe('WidgetsGrid', () => {
  beforeEach(async () => {
    layoutsStorageMock.get.mockReset();
    layoutsStorageMock.set.mockReset();
    layoutsStorageMock.remove.mockReset();
    ({ default: Grid } = await import('@/components/shared/Widget/Grid.vue'));
  });

  it('emits widgets visibility model based on the active layout', async () => {
    const wrapper = await mountGrid();

    const emitted = wrapper.emitted('input') ?? [];
    expect(emitted.length).toBeGreaterThan(0);
    const [model] = emitted[emitted.length - 1];
    expect(Object.keys(wrapper.vm.layouts)).toContain('lg');
    expect((wrapper.vm.layouts.lg ?? []).length).toBeGreaterThan(0);
    expect((wrapper.props('defaultLayouts') as ResponsiveLayouts).lg?.length).toBeGreaterThan(0);
    expect(wrapper.vm.layout.length).toBeGreaterThan(0);
    expect(model).toEqual({
      'widget-1': true,
      'widget-2': false,
    });
  });

  it('updates widget height while resizing and persists layouts', async () => {
    const wrapper = await mountGrid();

    wrapper.vm.layout = [
      {
        i: 'widget-1',
        x: 0,
        y: 0,
        w: 4,
        h: 1,
        minH: 1,
      },
    ] as unknown as Layout;

    wrapper.vm.onResize('widget-1', { width: 0, height: 60 });
    expect(wrapper.vm.layout[0].h).toBeGreaterThan(1);

    const updatedLayout = [
      {
        i: 'widget-1',
        x: 0,
        y: 0,
        w: 4,
        h: 2,
        moved: true,
      },
    ] as unknown as Layout;

    wrapper.vm.onLayoutUpdate(updatedLayout);
    expect(layoutsStorageMock.set).toHaveBeenCalledWith(
      'test-grid',
      expect.stringContaining('"widget-1"')
    );
  });
});

import { mount } from '@vue/test-utils';
import { describe, expect, it } from 'vitest';

const LoadingDirective = {
  mounted: () => undefined,
};

import IFrameWidget from '@/components/shared/Widget/IFrame.vue';

describe('IFrameWidget', () => {
  it('shows loading initially when src provided and hides after load', async () => {
    const wrapper = mount(IFrameWidget, {
      props: { src: 'https://example.com/frame' },
      global: {
        directives: {
          loading: LoadingDirective,
        },
      },
    });

    const vm = wrapper.vm as unknown as {
      $: { exposed?: { widgetLoading?: { value: boolean } }; setupState: { widgetLoading?: { value: boolean } } };
    };
    const widgetLoading = vm.$.exposed?.widgetLoading ?? vm.$.setupState.widgetLoading;
    expect(widgetLoading?.value).toBe(true);

    const onLoadWidget = (wrapper.vm as unknown as { $: { setupState: { onLoadWidget?: () => void } } }).$
      .setupState.onLoadWidget;
    onLoadWidget?.();
    expect(widgetLoading?.value).toBe(false);
  });

  it('applies bordered styling when requested', () => {
    const wrapper = mount(IFrameWidget, {
      props: { withBorder: true },
      global: {
        directives: {
          loading: LoadingDirective,
        },
      },
    });

    expect(wrapper.find('.widget-container').classes()).toContain('widget-container--bordered');
  });
});

import { FPNumber } from '@sora-substrate/sdk';
import { reactive } from 'vue';
import { createPinia, setActivePinia } from 'pinia';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import { PageNames } from '@/consts';
import router from '@/router';
import { useBridgeFormStore } from '@/stores/bridge/form';

vi.mock('@/stores/assets', () => ({
  useAssetsStore: () => ({
    assetDataByAddress: () =>
      ({
        address: 'xor',
        externalAddress: 'xor-external',
        symbol: 'XOR',
        decimals: 12,
        externalDecimals: 18,
      }) as RegisteredAssetMock,
  }),
}));

type RegisteredAssetMock = {
  address: string;
  externalAddress: string;
  symbol: string;
  decimals: number;
  externalDecimals: number;
};

type StoreStub = {
  state: {
    bridge: {
      isSoraToEvm: boolean;
      externalNativeBalance: string;
      assetLockedBalance: FPNumber;
      assetExternalMinBalance: string;
      outgoingMinLimit: FPNumber;
      outgoingMaxLimit: FPNumber;
      incomingMinLimit: FPNumber;
      soraNetworkFee: string;
      externalTransferFee: string;
    };
    web3: {
      networkSelected: number;
      networkType: number;
    };
    assets: Record<string, unknown>;
  };
  getters: {
    bridge: ReturnType<typeof reactive>;
    web3: ReturnType<typeof reactive>;
    assets: ReturnType<typeof reactive>;
  };
  store: {
    state: StoreStub['state'];
    getters: StoreStub['getters'];
  };
};

const createRegisteredAsset = (overrides: Partial<RegisteredAssetMock> = {}): RegisteredAssetMock => ({
  address: '0xasset',
  externalAddress: '0xasset-external',
  symbol: 'VAL',
  decimals: 12,
  externalDecimals: 18,
  ...overrides,
});

const createStoreStub = (): StoreStub => {
  const state = reactive({
    bridge: {
      isSoraToEvm: true,
      externalNativeBalance: '0',
      assetLockedBalance: new FPNumber(50),
      assetExternalMinBalance: '0',
      outgoingMinLimit: new FPNumber(1),
      outgoingMaxLimit: new FPNumber(40),
      incomingMinLimit: new FPNumber('0.5'),
      soraNetworkFee: '1000000000000',
      externalTransferFee: '2000000000000000000',
    },
    web3: {
      networkSelected: 0,
      networkType: 0,
    },
    assets: {},
  });

  const bridgeGetters = reactive({
    asset: createRegisteredAsset(),
    nativeToken: createRegisteredAsset({
      address: '0xnative',
      symbol: 'XOR',
      externalDecimals: 18,
    }),
    sender: 'soraAddress',
    recipient: 'evmAddress',
    isNativeTokenSelected: false,
    isSidechainAsset: true,
    externalNetworkFee: '300000000000000000',
  });

  const getters = {
    bridge: bridgeGetters,
    web3: reactive({
      isValidNetwork: true,
    }),
    assets: reactive({
      xor: createRegisteredAsset({
        address: 'xor',
        symbol: 'XOR',
        decimals: 12,
        externalDecimals: 18,
      }),
    }),
  };

  return {
    state,
    getters,
    store: {
      state,
      getters,
    },
  };
};

let storeStub: StoreStub;
let useBridgeCore: () => ReturnType<(typeof import('@/composables/useBridgeCore'))['useBridgeCore']>;
let routerPush: ReturnType<typeof vi.spyOn>;
let bridgeFormStore: ReturnType<typeof useBridgeFormStore>;

const syncBridgeFormStore = () => {
  if (!bridgeFormStore) return;

  bridgeFormStore.$patch({
    externalNativeBalance: storeStub.state.bridge.externalNativeBalance,
    assetLockedBalance: storeStub.state.bridge.assetLockedBalance,
    assetExternalMinBalance: storeStub.state.bridge.assetExternalMinBalance,
    outgoingMinLimit: storeStub.state.bridge.outgoingMinLimit,
    outgoingMaxLimit: storeStub.state.bridge.outgoingMaxLimit,
    incomingMinLimit: storeStub.state.bridge.incomingMinLimit,
    soraNetworkFee: storeStub.state.bridge.soraNetworkFee,
    externalTransferFee: storeStub.state.bridge.externalTransferFee,
    externalNetworkFee: storeStub.getters.bridge.externalNetworkFee,
  });
};

const resetStore = () => {
  Object.assign(storeStub.state.bridge, {
    isSoraToEvm: true,
    externalNativeBalance: '5000000000000000000',
    assetLockedBalance: new FPNumber(50),
    assetExternalMinBalance: '100000000000000000',
    outgoingMinLimit: new FPNumber(1),
    outgoingMaxLimit: new FPNumber(40),
    incomingMinLimit: new FPNumber('0.5'),
    soraNetworkFee: '1000000000000',
    externalTransferFee: '2000000000000000000',
  });

  Object.assign(storeStub.getters.bridge, {
    asset: createRegisteredAsset(),
    nativeToken: createRegisteredAsset({
      address: '0xnative',
      symbol: 'XOR',
      externalDecimals: 18,
    }),
    sender: 'soraAddress',
    recipient: 'evmAddress',
    isNativeTokenSelected: false,
    isSidechainAsset: true,
    externalNetworkFee: '300000000000000000',
  });

  syncBridgeFormStore();
  routerPush.mockClear();
};

beforeEach(async () => {
  storeStub = createStoreStub();
  vi.doMock('@/store', () => ({
    default: storeStub.store,
  }));
  setActivePinia(createPinia());
  bridgeFormStore = useBridgeFormStore();
  const module = await import('@/composables/useBridgeCore');
  useBridgeCore = module.useBridgeCore;
  routerPush = vi.spyOn(router, 'push').mockResolvedValue();
  resetStore();
});

afterEach(() => {
  vi.doUnmock('@/store');
  vi.resetModules();
  routerPush.mockRestore();
  bridgeFormStore.$reset();
});

describe('useBridgeCore', () => {
  it('exposes bridge state and computed limits', () => {
    const core = useBridgeCore();

    expect(core.isSoraToEvm.value).toBe(true);
    expect(core.asset.value?.symbol).toBe('VAL');
    expect(core.nativeTokenSymbol.value).toBe('XOR');
    expect(core.nativeTokenDecimals.value).toBe(18);

    expect(core.outgoingMaxAmount.value?.toString()).toBe('40');
    expect(core.getTransferMaxAmount(true)?.toString()).toBe('40');

    const expectedMin = core.outgoingMinLimit.value?.add(core.externalTransferFeeFP.value);
    expect(core.outgoingMinAmount.value?.toString()).toBe(expectedMin?.toString());

    expect(core.isGreaterThanTransferMaxAmount('55', core.asset.value, true, true)).toBe(true);
    expect(core.isGreaterThanTransferMaxAmount('10', core.asset.value, true, true)).toBe(false);

    expect(core.isLowerThanTransferMinAmount('0.1', core.asset.value, true, true)).toBe(true);
    expect(core.isLowerThanTransferMinAmount('10', core.asset.value, true, true)).toBe(false);
  });

  it('derives incoming limits for non sidechain assets', () => {
    storeStub.getters.bridge.isSidechainAsset = false;

    const core = useBridgeCore();

    expect(core.incomingMaxAmount.value?.toString()).toBe('50');
    expect(core.getTransferMaxAmount(false)?.toString()).toBe('50');
    expect(core.getTransferMinAmount(false)?.toString()).toBe(
      storeStub.state.bridge.incomingMinLimit.toString()
    );
  });

  it('calculates transfer bounds using FPNumber conversions to prevent rounding regressions', () => {
    storeStub.state.bridge.outgoingMinLimit = new FPNumber('1.2345');
    storeStub.state.bridge.outgoingMaxLimit = new FPNumber('25.6789');
    storeStub.state.bridge.assetLockedBalance = new FPNumber('20.1234');
    storeStub.state.bridge.externalTransferFee = '450000000000000000'; // 0.45 with 18 decimals
    storeStub.state.bridge.incomingMinLimit = new FPNumber('0.75');

    storeStub.getters.bridge.asset = createRegisteredAsset({
      symbol: 'VAL',
      externalDecimals: 18,
    });
    storeStub.getters.bridge.isSidechainAsset = true;

    syncBridgeFormStore();

    const core = useBridgeCore();

    const expectedFee = FPNumber.fromCodecValue(storeStub.state.bridge.externalTransferFee, 18);
    expect(core.externalTransferFeeFP.value?.eq(expectedFee)).toBe(true);

    const expectedMin = storeStub.state.bridge.outgoingMinLimit.add(expectedFee);
    expect(core.outgoingMinAmount.value?.eq(expectedMin)).toBe(true);

    const expectedMax = FPNumber.min(
      storeStub.state.bridge.outgoingMaxLimit,
      storeStub.state.bridge.assetLockedBalance
    ) as FPNumber;
    expect(core.outgoingMaxAmount.value?.eq(expectedMax)).toBe(true);

    const aboveMax = expectedMax.add(new FPNumber('0.0001')).toString();
    expect(core.isGreaterThanTransferMaxAmount(aboveMax, core.asset.value, true, true)).toBe(true);
    expect(core.isGreaterThanTransferMaxAmount(expectedMax.toString(), core.asset.value, true, true)).toBe(false);

    const belowMin = expectedMin.sub(new FPNumber('0.0001')).toString();
    expect(core.isLowerThanTransferMinAmount(belowMin, core.asset.value, true, true)).toBe(true);
    expect(core.isLowerThanTransferMinAmount(expectedMin.toString(), core.asset.value, true, true)).toBe(false);

    storeStub.getters.bridge.isSidechainAsset = false;
    const incomingMin = core.getTransferMinAmount(false);
    expect(incomingMin?.eq(storeStub.state.bridge.incomingMinLimit)).toBe(true);
  });

  it('navigates to bridge pages via router', () => {
    const core = useBridgeCore();

    core.handleViewTransactionsHistory();
    expect(routerPush).toHaveBeenCalledWith({ name: PageNames.BridgeTransactionsHistory });

    core.navigateToBridge();
    expect(routerPush).toHaveBeenCalledWith({ name: PageNames.Bridge });
  });
});

import { computed } from 'vue';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import { BridgeNetworkType } from '@sora-substrate/sdk/build/bridgeProxy/consts';

import { useBridgeTransaction } from '@/composables/useBridgeTransaction';

const mocks = vi.hoisted(() => {
  const soraExplorerLinksMock = vi.fn(() => ['sora-link']);
  const getNetworkExplorerLinksMock = vi.fn(() => ['network-link']);
  const getNetworkNameMock = vi.fn(() => 'Ethereum');
  const isOutgoingTxMock = vi.fn(() => true);

  return {
    soraExplorerLinksMock,
    getNetworkExplorerLinksMock,
    getNetworkNameMock,
    isOutgoingTxMock,
  };
});

vi.mock('@/utils', () => ({
  soraExplorerLinks: mocks.soraExplorerLinksMock,
}));

vi.mock('@/composables/useNetworkFormatter', () => ({
  useNetworkFormatter: () => ({
    soraNetwork: computed(() => 'testnet'),
    getNetworkExplorerLinks: mocks.getNetworkExplorerLinksMock,
    getNetworkName: mocks.getNetworkNameMock,
    isOutgoingTx: mocks.isOutgoingTxMock,
    TranslationConsts: {
      Sora: 'Sora',
      Max: '≈',
    },
    EvmLinkType: {
      Transaction: 'tx',
      Account: 'account',
    },
  }),
}));

const {
  soraExplorerLinksMock,
  getNetworkExplorerLinksMock,
  getNetworkNameMock,
  isOutgoingTxMock,
} = mocks;

type BridgeTransactionMock = {
  from?: string;
  to?: string;
  txId?: string;
  hash?: string;
  blockHeight?: number;
  blockId?: string;
  payload?: { eventIndex?: number };
  externalHash?: string;
  externalBlockHeight?: number;
  externalBlockId?: string;
  externalEventIndex?: number;
  externalNetworkType?: BridgeNetworkType;
  externalNetwork?: number;
};

const baseTx: BridgeTransactionMock = {
  from: 'sora-address',
  to: 'external-address',
  txId: 'tx-1',
  hash: 'hash-1',
  blockHeight: 42,
  blockId: 'block-1',
  payload: { eventIndex: 3 },
  externalHash: '0xabc',
  externalBlockHeight: 128,
  externalBlockId: '0xblock',
  externalEventIndex: 7,
  externalNetworkType: BridgeNetworkType.Evm,
  externalNetwork: 1,
};

const createComposable = (overrides: Partial<BridgeTransactionMock> = {}) => {
  const tx = computed(() => ({
    ...baseTx,
    ...overrides,
  }));

  return useBridgeTransaction(tx);
};

describe('useBridgeTransaction', () => {
  beforeEach(() => {
    soraExplorerLinksMock.mockClear();
    getNetworkExplorerLinksMock.mockClear();
    getNetworkNameMock.mockClear();
    isOutgoingTxMock.mockClear();
    isOutgoingTxMock.mockReturnValue(true);
  });

  it('derives core explorer metadata for outgoing transactions', () => {
    const bridgeTx = createComposable();

    expect(bridgeTx.isOutgoing.value).toBe(true);
    expect(bridgeTx.txInternalAccount.value).toBe(baseTx.from);
    expect(bridgeTx.txExternalAccount.value).toBe(baseTx.to);

    expect(bridgeTx.internalExplorerLinks.value).toEqual(['sora-link']);
    expect(soraExplorerLinksMock).toHaveBeenCalledWith(
      'testnet',
      baseTx.txId,
      baseTx.blockHeight,
      baseTx.payload?.eventIndex
    );

    expect(bridgeTx.externalExplorerLinks.value).toEqual(['network-link']);
    expect(getNetworkExplorerLinksMock).toHaveBeenCalledWith(
      baseTx.externalNetworkType,
      baseTx.externalNetwork,
      baseTx.externalHash,
      baseTx.externalBlockHeight,
      baseTx.externalEventIndex
    );

    expect(bridgeTx.externalAccountLinks.value).toEqual(['network-link']);
    expect(getNetworkExplorerLinksMock).toHaveBeenLastCalledWith(
      baseTx.externalNetworkType,
      baseTx.externalNetwork,
      baseTx.to,
      undefined,
      undefined,
      bridgeTx.EvmLinkType.Account
    );
  });

  it('builds network text with approximate prefix when requested', () => {
    const bridgeTx = createComposable();
    const text = bridgeTx.getNetworkText('pending', baseTx.externalNetwork, { approximate: true });

    expect(text).toBe('≈ Ethereum pending');
    expect(getNetworkNameMock).toHaveBeenCalledWith(baseTx.externalNetworkType, baseTx.externalNetwork);
  });

  it('detects non-evm transaction types and respects direction helper', () => {
    isOutgoingTxMock.mockReturnValueOnce(false);

    const bridgeTx = createComposable({
      externalNetworkType: undefined,
      externalNetwork: undefined,
    });

    expect(bridgeTx.isOutgoing.value).toBe(false);
    expect(bridgeTx.isEvmTxType.value).toBe(false);
    expect(bridgeTx.externalExplorerLinks.value).toEqual([]);
    expect(bridgeTx.externalAccountLinks.value).toEqual([]);
    expect(getNetworkExplorerLinksMock).not.toHaveBeenCalled();
  });
});

import { nextTick, ref } from 'vue';
import { describe, expect, it, vi, beforeEach } from 'vitest';

import { PageNames } from '@/consts';

const addressRef = ref('alice');
const isLoggedInRef = ref(false);
const logoutMock = vi.fn();
const setDialogVisibilityMock = vi.fn();
const goToMock = vi.fn();

vi.mock('@/stores/wallet', () => ({
  useWalletStore: () => ({
    get address() {
      return addressRef.value;
    },
    get isLoggedIn() {
      return isLoggedInRef.value;
    },
    logout: logoutMock,
  }),
}));

const storeMock = {
  commit: {
    web3: {
      setSoraAccountDialogVisibility: setDialogVisibilityMock,
    },
  },
};

vi.mock('@/store', () => ({
  default: storeMock,
}));

vi.mock('@/router', () => ({
  __esModule: true,
  goTo: goToMock,
  lazyComponent: () => ({ template: '<div class="router-lazy-component-stub"><slot /></div>' }),
}));

describe('useInternalConnect', () => {
  beforeEach(() => {
    addressRef.value = 'alice';
    isLoggedInRef.value = false;
    logoutMock.mockClear();
    setDialogVisibilityMock.mockClear();
    goToMock.mockClear();
  });

  it('exposes reactive wallet state and connection helpers', async () => {
    const { soraAddress, isLoggedIn, connectSoraWallet, disconnectSoraWallet, navigateToWallet } =
      await import('@/composables/useInternalConnect').then((m) => m.useInternalConnect());

    expect(soraAddress.value).toBe('alice');
    expect(isLoggedIn.value).toBe(false);

    addressRef.value = 'bob';
    isLoggedInRef.value = true;
    await nextTick();

    expect(soraAddress.value).toBe('bob');
    expect(isLoggedIn.value).toBe(true);

    connectSoraWallet();
    expect(setDialogVisibilityMock).toHaveBeenCalledWith(true);

    disconnectSoraWallet();
    expect(logoutMock).toHaveBeenCalledTimes(1);

    navigateToWallet();
    expect(goToMock).toHaveBeenCalledWith(PageNames.Wallet);
  });
});

