    mockStore.state.demeterFarming.pools = [
      {
        baseAsset: 'A',
        poolAsset: 'B',
        rewardAsset: 'R',
        isFarm: true,
        isRemoved: false,
        multiplier: '2',
        totalTokensInPool: new FPNumber(500),
